(function(){
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s)); const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const fmt=(x,d=1)=>Number.isFinite(x)?x.toFixed(d):"-", pct=x=>Math.round(x*100)+"%", money=(x,c)=>(c||"")+" "+Math.round(x||0).toLocaleString();
const ARO={HVW:24000000}; // illustrative accounting provision for the demonstration record const KEY="lataf.records.v1";
// ---------- Records: one editable record per site, persisted in the browser (export/import JSON for the repository)
function seedRecord(code){ const s=DATA.sites[code]; const crit=DATA.ids.map((id,k)=>({id,rating:s.ratings[k],grade:s.grades[k],delib:(s.delib||{})[id]||null,facilities:(s.facilities||{})[id]?s.facilities[id].map(x=>({name:x[0],sub:x[1],basis:x[2],applicable:true})):null,citation:(s.citations||{})[id]||"",up:"",down:"",accepted:false,override:""}));
  return {code,name:s.name,country:s.country,jurisdiction:s.jurisdiction,pathway:s.pathway,institutionDependent:s.institutionDependent,basis:s.basis,currency:s.currency,recurring:s.recurring,aro:ARO[code]||0,toa:s.toa33,toaAuto:false,jur:(s.jur_ind||[]).map(x=>({id:x[0],name:x[1],value:x[2]||2})),profile:Object.assign({},s.profile||{}),evidenceSub:Object.assign({},s.evidence_sub||{availability:3,quality:3,documentation:3,currency:3,verification:3}),
    criteria:crit, evidence:(s.documents||[]).map(d=>Object.assign({source:"Library"},d)), rva:[], findings:[], gaps:(s.gaps||[]).map(g=>Object.assign({cost:null},g)), tier2:(s.tier2||[]).map(t=>Object.assign({open:true},t)), risks:s.risks||[], opps:(s.opps||[]).map(o=>Object.assign({status:"Registered",votes:{}},o)), t2f:JSON.parse(JSON.stringify(s.t2f||{})), roadmap:s.roadmap||[], actions:[], fincase:Object.assign({horizon:50,rate:0.05},s.fincase||{}), ledger:null,
    interviews:[], workshop:{date:"",parties:[],agenda:[],goals:[],ideas:[],parking:[],owed:[]}, state:"Draft", revision:2, revisions:[{rev:1,when:"2026-10-31",who:"",version:"v3.3",th:"A",tri:s.tri32||0,lo:0,hi:0,decision:"desktop record",band:"",state:"Draft",basis:s.basis,criteria:crit.map(c=>({id:c.id,rating:c.rating,grade:c.grade})),jur:(s.jur_ind||[]).map(x=>x[2]||2),toa:s.toa33,gaps:(s.gaps||[]).filter(g=>g.critical).length,note:"Illustrative desktop record (fictional demonstration)"}], changeLog:[{when:new Date().toISOString().slice(0,10),what:"Record seeded from the fictional demonstration record (all values illustrative)",who:""}]}; }
function blankRecord(code,name){ const r=seedRecord("HVW"); Object.assign(r,{code,name,country:"",jurisdiction:"",pathway:"Long-term stewardship",institutionDependent:false,basis:"Desktop (new)",currency:"USD",recurring:0,aro:0,toa:0,toaAuto:true,profile:{},evidence:[],evidenceSub:{availability:3,quality:3,documentation:3,currency:3,verification:3},gaps:[],tier2:[],risks:[],opps:[],roadmap:[],actions:[],fincase:{baseline:0,future:0,investment:0,period:3,horizon:50,rate:0.05},ledger:null,interviews:[],changeLog:[{when:new Date().toISOString().slice(0,10),what:"New site created",who:""}]});
  r.jur=r.jur.map(j=>Object.assign({},j,{value:2})); r.criteria=DATA.ids.map(id=>({id,rating:3,grade:"E4",delib:null,facilities:null,citation:"",up:"",down:"",accepted:false,override:""})); r.t2f={}; for(const p of ["Relinquishment","Divestment","Third-party transfer","Accelerated closure","Reduced care and maintenance","Long-term stewardship"]) r.t2f[p]=["Unknown","Unknown","Unknown","Unknown","Unknown","Unknown"]; return r; }
let DB=null; function load(){ try{ DB=JSON.parse(localStorage.getItem(KEY)); }catch(e){ DB=null; } if(!DB||!DB.records){ DB={records:{},current:"HVW"}; for(const c of Object.keys(DATA.sites)) DB.records[c]=seedRecord(c); } for(const c of Object.keys(DATA.sites)) if(!DB.records[c]) DB.records[c]=seedRecord(c); }
function save(){ try{ localStorage.setItem(KEY,JSON.stringify(DB)); }catch(e){} }
function log(rec,what){ rec.changeLog.unshift({when:new Date().toISOString().slice(0,10),what,who:rec.profile["Lead assessor (Assessor A)"]||""}); if(rec.changeLog.length>200) rec.changeLog.length=200; }
const state={version:"v3.3",th:"A",rho:0.6,budget:500000,useIllustrative:false,tab:"walk"};
const rec=()=>DB.records[DB.current];
// ---------- Engine adapters
function jciLevel(r){ const g={RC:[],IC:[],SC:[],PL:[]}; for(const j of r.jur){ const k=j.id.slice(0,2); if(g[k]) g[k].push(+j.value||1); } const sub=Object.fromEntries(Object.entries(g).map(([k,v])=>[k,v.length?Math.max(...v):1])); return {sub,jci:Math.max(...Object.values(sub))}; }
function toaShare(r){ if(!r.toaAuto) return +r.toa||0; const open=r.tier2.filter(t=>t.open); return -Math.min(0.26, open.reduce((a,t)=>a+(+t.release||0.03),0)); }
function engineOpts(r,over={}){ return Object.assign({version:state.version,thresholds:state.th,jci:jciLevel(r).jci,institutionDependent:!!r.institutionDependent,toa:toaShare(r),weakestSub:Math.min(...Object.values(r.evidenceSub).map(Number)),openCritical:r.gaps.filter(g=>g.critical&&(g.status||"Open")!=="Closed").length},over); }
const crits=r=>r.criteria.map(c=>({id:c.id,rating:+c.rating,grade:c.grade,delib:c.delib,facilities:c.facilities?c.facilities.filter(f=>f.applicable):null}));
function badge(t){ const m={"Proceed":"ok","Proceed with validation":"warn","Reassess pathway":"amber","Escalate decision":"bad"}; return `<span class="badge ${m[t]||''}">${esc(t)}</span>`; } const catClass=c=>c.startsWith("Transition ready")?"ok":c.startsWith("Transition achievable")?"good":c.startsWith("Significant")?"amber":"bad";
// ---------- Generic editable grid
function grid(host, rows, cols, onChange, opts={}){ const head=cols.map(c=>`<th>${esc(c.label)}</th>`).join("")+(opts.noDelete?"":"<th></th>");
  const body=rows.map((row,i)=>`<tr>${cols.map(c=>{ const v=row[c.k]??""; if(c.type==="select") return `<td><select data-g="${i}|${c.k}">${c.options.map(o=>`<option ${String(o)===String(v)?"selected":""}>${esc(o)}</option>`).join("")}</select></td>`; if(c.type==="num") return `<td><input type="number" data-g="${i}|${c.k}" value="${esc(v)}" step="${c.step||1}"></td>`; if(c.type==="ro") return `<td><small>${esc(v)}</small></td>`; return `<td><textarea rows="2" data-g="${i}|${c.k}">${esc(v)}</textarea></td>`; }).join("")}${opts.noDelete?"":`<td><button class="mini" data-del="${i}">×</button></td>`}</tr>`).join("");
  host.innerHTML=`<div class="scroll"><table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>${opts.noAdd?"":`<p><button data-add="1">+ Add row</button></p>`}`;
  host.querySelectorAll('[data-g]').forEach(el=>el.addEventListener('change',e=>{ const [i,k]=e.target.dataset.g.split("|"); const col=cols.find(c=>c.k===k); rows[+i][k]=col.type==="num"?(e.target.value===""?null:+e.target.value):e.target.value; onChange(); }));
  host.querySelectorAll('[data-del]').forEach(el=>el.addEventListener('click',e=>{ rows.splice(+e.target.dataset.del,1); onChange(true); }));
  const add=host.querySelector('[data-add]'); if(add) add.addEventListener('click',()=>{ const n={}; cols.forEach(c=>n[c.k]=c.type==="num"?null:(c.type==="select"?c.options[0]:"")); if(opts.newRow) Object.assign(n,opts.newRow(rows.length)); rows.push(n); onChange(true); }); }
// ---------- Tabs
const TABS=[["walk","Walkthrough"],["profile","1 Asset profile"],["evidence","2 Evidence & gaps"],["docs","3 Documents & extraction"],["rva","4 Requirements vs assumptions"],["readiness","5 Readiness & engine"],["jur","6 Jurisdiction"],["interview","Interviews & questionnaire"],["workshop","Workshop"],["probability","Probability & robustness"],["infoplan","Information plan (VoI)"],["tier2","Tier 2 findings & registers"],["pathways","Pathways & land use"],["ledger","Cost-to-risk ledger"],["tier3","Tier 3 case & roadmap"],["cons","Stacked conservatism"],["graph","Evidence graph & narrative"],["decisions","Decision ledger & package"],["qa","QA, revisions & review"],["board","Review board"],["command","Portfolio command view"],["invest","Portfolio investment optimiser"],["calib","Calibration & learning"],["portfolio","Portfolio"],["library","Library & triggers"],["export","Sites, export & import"],["newsite","+ New site"]];
function renderTab(){ const r=rec(); const el=$("#panel"); el.innerHTML=""; if(!r){ rNewSite(null,el); save(); return; } ({walk:rWalk,docs:rDocsTab,board:rBoard,newsite:rNewSite,cons:rCons,graph:rGraph,decisions:rDecisions,command:rCommand,invest:rInvest,calib:rCalib,profile:rProfile,evidence:rEvidence,rva:rRva,readiness:rReadiness,jur:rJur,interview:rInterview,workshop:rWorkshop,probability:rProb,infoplan:rInfo,tier2:rTier2,pathways:rPath,ledger:rLedger,tier3:rTier3,qa:rQA,portfolio:rPortfolio,library:rLibrary,export:rExport})[state.tab](r,el); save(); }
// ---------- Walkthrough
function rWalk(r,el){ const res=LATAF.run(crits(r),engineOpts(r)); const steps=walkSteps(r); const mc=LATAF.simulate(crits(r),engineOpts(r),3000,1); const P=x=>Math.round(100*x);
  el.innerHTML=`<div class="card"><h3>Walkthrough - ${esc(r.name)} <span class="tag">${esc(r.state)} · revision ${r.revision} · ${completeness(r)}% complete</span></h3><p class="muted">Work top to bottom; each step is a tab and the tick shows whether the record carries enough to move on. <b>Next action: ${esc(nextAction(r))}.</b></p>
  <div class="kpis"><div class="kpi"><small>Headline</small>${badge(res.decision)}</div><div class="kpi"><small>Balance-of-evidence TRI [range]</small><b>${fmt(res.TRI)} <span class="muted">[${fmt(res.TRI_low)}-${fmt(res.TRI_high)}]</span></b></div><div class="kpi"><small>Expected TRI (MC p50) · p10-p90</small><b>${fmt(mc.p50)} <span class="muted">${fmt(mc.p10)}-${fmt(mc.p90)}</span></b></div><div class="kpi"><small>P(ready / achievable / barriers / reassess)</small><b>${P(mc.probs.ready)} / ${P(mc.probs.achievable)} / ${P(mc.probs.barriers)} / ${P(mc.probs.reassess)} %</b></div><div class="kpi"><small>Distance to nearest threshold</small><b>${res.distance>=0?"+":""}${fmt(res.distance)} pts (${res.nearest})</b></div><div class="kpi"><small>Rule set</small><b>${esc(LATAF.RULES[state.version].label)}</b></div></div>
  <ol class="steps">${steps.map(([t,tab,ok,d])=>`<li><span class="${ok?'tick':'cross'}">${ok?'✓':'○'}</span> <button class="link" data-go="${tab}">${esc(t)}</button><br><small>${esc(d)}</small></li>`).join("")}</ol>
  <p class="muted">Process rules carried from the pilot: worked example first in the room, technical criteria by facility, then the other dimensions, evidence questions last (CAL-22); reconcile, never average (CAL-24); both voiced ratings recorded (CAL-29); the engine computes, people decide (CAL-39). Freeze a revision at each milestone (QA tab) so every change has a baseline (CAL-38).</p></div>`;
  el.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',e=>go(e.target.dataset.go))); }
function go(tab){ state.tab=tab; $$('nav button').forEach(x=>x.classList.toggle('on',x.dataset.tab===tab)); renderTab(); }
// ---------- 1 Profile
const PROFILE_FIELDS=["Country","Region","Jurisdiction (state / province, principal regulator)","Asset type","Closure stage","Ownership structure","Obligation holder (legal entity)","Land tenure","Intended future state (as stated by the owner - never assumed)","Current / planned transition pathway","Review boundary (assets, tenements, timeframe in scope)","Decision statement","Decision owner","Decision date","Kill criteria","Remaining one-off closure cost (USD)","Annual recurring care, monitoring and treatment cost (USD/yr)","Closure liability - accounting provision / ARO (USD)","Currency and price year of EACH figure above (v3.2)","Duration class (1 defined end date, 2 <10 yrs, 3 10-30 yrs, 4 indefinite)","Highest consequence class on site (corporate matrix 1-5)","Hard statutory deadline (if any)","Primary archetype","Site attribute tags (comma separated)","Corporate transition objective for this asset (CAL-33)","Alignment of the preferred pathway (Aligned / Partly / Divergent)","Materiality class (drives re-screen cadence)","Lead assessor (Assessor A)","Second assessor (Assessor B)","Independent reviewer / challenger"];
function rProfile(r,el){ const keys=Array.from(new Set(PROFILE_FIELDS.concat(Object.keys(r.profile).map(k=>k)))); const rows=keys.map(k=>`<tr><td style="width:34%"><b>${esc(k)}</b></td><td><textarea rows="2" data-pf="${esc(k)}">${esc(r.profile[k]||r.profile[Object.keys(r.profile).find(x=>x.startsWith(k.slice(0,30)))]||"")}</textarea></td></tr>`).join("");
  el.innerHTML=`<div class="card"><h3>1 Asset profile - ${esc(r.name)}</h3><p class="muted">Blocks A-F of the record. Pathway and currency drive the engine and the optimiser.</p>
  <div class="kpis"><div class="kpi"><small>Pathway</small><select id="pw">${["Relinquishment","Divestment","Third-party transfer","Accelerated closure","Reduced care and maintenance","Long-term stewardship"].map(p=>`<option ${p===r.pathway?"selected":""}>${p}</option>`).join("")}</select></div><div class="kpi"><small>Institution-dependent (JCA applies under v3.3)</small><select id="inst"><option value="1" ${r.institutionDependent?"selected":""}>Yes</option><option value="0" ${!r.institutionDependent?"selected":""}>No</option></select></div><div class="kpi"><small>Recurring cost / yr</small><input type="number" id="recur" value="${r.recurring}"></div><div class="kpi"><small>Provision / ARO</small><input type="number" id="aro" value="${r.aro}"></div><div class="kpi"><small>Currency and price year</small><input id="ccy" value="${esc(r.currency)}"></div><div class="kpi"><small>Evidence basis</small><input id="basis" value="${esc(r.basis)}"></div></div>
  <table><tbody>${rows}</tbody></table></div>`;
  el.querySelectorAll('[data-pf]').forEach(t=>t.addEventListener('change',e=>{ r.profile[e.target.dataset.pf]=e.target.value; log(r,"Profile: "+e.target.dataset.pf); save(); }));
  $("#pw").addEventListener('change',e=>{r.pathway=e.target.value; log(r,"Pathway set to "+r.pathway); save();}); $("#inst").addEventListener('change',e=>{r.institutionDependent=e.target.value==="1"; save();}); $("#recur").addEventListener('change',e=>{r.recurring=+e.target.value; save();}); $("#aro").addEventListener('change',e=>{r.aro=+e.target.value; save();}); $("#ccy").addEventListener('change',e=>{r.currency=e.target.value; save();}); $("#basis").addEventListener('change',e=>{r.basis=e.target.value; save();}); }
// ---------- 2 Evidence & gaps
function rEvidence(r,el){ el.innerHTML=`<div class="card"><h3>2 Evidence register, sub-ratings and gaps - ${esc(r.name)}</h3><p class="muted">One row per document (grade by provenance, not by age - CAL-19). Sub-ratings 1-5 set the weakest evidence sub-rating used by the confidence class. Gaps carry the cost to close (CAL-40).</p>
  <h4>Evidence sub-ratings</h4><div class="kpis">${Object.keys(r.evidenceSub).map(k=>`<div class="kpi"><small>${k}</small><input type="number" min="1" max="5" data-es="${k}" value="${r.evidenceSub[k]}"></div>`).join("")}</div>
  <h4>Evidence items</h4><div id="evg"></div><h4>Gaps and information requests</h4><div id="gapg"></div></div>`;
  el.querySelectorAll('[data-es]').forEach(i=>i.addEventListener('change',e=>{ r.evidenceSub[e.target.dataset.es]=+e.target.value; save(); }));
  grid($("#evg"),r.evidence,[{k:"id",label:"Evidence ID"},{k:"title",label:"Title"},{k:"type",label:"Type"},{k:"date",label:"Date / version"},{k:"grade",label:"Grade",type:"select",options:["E1","E2","E3","E4"]},{k:"source",label:"Source class",type:"select",options:["Client","Regulator","Public","Consultant"]},{k:"usedFor",label:"Used for (criteria)"},{k:"clause",label:"Clause / page"}],()=>{save();},{newRow:n=>({id:`EV-${r.code}-${String(n+1).padStart(2,"0")}`})});
  grid($("#gapg"),r.gaps,[{k:"id",label:"Gap ID"},{k:"topic",label:"Topic / dataset missing"},{k:"affects",label:"Decision it affects"},{k:"consequence",label:"Consequence 1-5",type:"num"},{k:"critical",label:"Could change the decision",type:"select",options:[true,false]},{k:"cost",label:"Cost to close",type:"num",step:1000},{k:"status",label:"Status",type:"select",options:["Open","Requested","Received","Closed"]}],()=>{save();},{newRow:n=>({id:`GAP-${r.code}-${String(n+1).padStart(2,"0")}`,criteria:[],critical:true,status:"Open"})}); }
// ---------- 3 RvA
function rRva(r,el){ el.innerHTML=`<div class="card"><h3>3 Requirements vs assumptions - ${esc(r.name)} (CAL-31)</h3><p class="muted">Every commitment in one of the proposal's four categories with its defined treatment: Binding (confirm source, trigger, owner), Interpreted and precedent (validate; test risk-based alternatives), Inherited and layered conservatism (stress-test and unstack: keep, retire, simplify or convert to an adaptive gate), Unknown (flag; define validation or escalate).</p><div id="rvag"></div><div class="kpis" id="rvak"></div></div>`;
  const cols=[{k:"id",label:"RVA ID"},{k:"feature",label:"Asset feature / activity"},{k:"statement",label:"Obligation as stated"},{k:"instrument",label:"Instrument and clause"},{k:"category",label:"Proposal category",type:"select",options:["Binding","Interpreted and precedent","Inherited and layered conservatism","Unknown or insufficient evidence"]},{k:"treatment",label:"Treatment",type:"select",options:["Confirm (non-negotiable)","Validate","Stress-test and unstack","Flag and validate / escalate"]},{k:"verb",label:"Cost verb (CAL-36)",type:"select",options:["Keep","Validate","Simplify","Reframe"]},{k:"evidence",label:"Evidence IDs"},{k:"owner",label:"Owner"},{k:"status",label:"Status",type:"select",options:["Open","Confirmed","Corrected","Disputed"]}];
  const kp=()=>{ const n={}; r.rva.forEach(x=>n[x.category]=(n[x.category]||0)+1); $("#rvak").innerHTML=Object.entries(n).map(([k,v])=>`<div class="kpi"><small>${esc(k)}</small><b>${v}</b></div>`).join("")||'<span class="muted">No rows yet.</span>'; };
  grid($("#rvag"),r.rva,cols,()=>{save();kp();},{newRow:n=>({id:`RVA-${r.code}-${String(n+1).padStart(2,"0")}`})}); kp(); }
// ---------- 4 Readiness
function rReadiness(r,el){ const o=engineOpts(r), res=LATAF.run(crits(r),o), R=LATAF.RULES[state.version]; const mcq=LATAF.simulate(crits(r),o,3000,1); const Pq=x=>Math.round(100*x);
  const rows=r.criteria.map((c,i)=>{ const cc=crits(r)[i]; const [lo,hi]=LATAF.bounds(cc,R); const used=LATAF.used(cc,R); const fac=c.facilities?`<div class="facs">${c.facilities.map((f,j)=>`<span class="tag">${esc(f.name)} <input type="number" min="1" max="5" data-fs="${i}|${j}" value="${f.sub}" style="width:44px"> <select data-fb="${i}|${j}"><option ${f.basis==="assessed"?"selected":""}>assessed</option><option ${f.basis==="visual"?"selected":""}>visual</option><option ${f.basis==="none"?"selected":""}>none</option></select> <label><input type="checkbox" data-fa="${i}|${j}" ${f.applicable?"checked":""}>applies</label></span>`).join("")}</div>`:(["T1","T3","T6"].includes(c.id)?`<button class="mini" data-addfac="${i}">+ facilities</button>`:"");
    return `<tr><td><b>${c.id}</b><br><small>${esc(LATAF.CRIT[c.id][2])}</small></td><td><input type="range" min="1" max="5" step="1" data-rate="${i}" value="${c.rating}"> <b>${c.rating}</b>${fac}</td><td><select data-grade="${i}">${["E1","E2","E3","E4","W"].map(g=>`<option ${g===c.grade?"selected":""}>${g}</option>`).join("")}</select><br><small>used ${used} · bounds ${lo}-${hi}</small></td><td><input data-delib="${i}" placeholder="e.g. 3-4" value="${c.delib?c.delib.join("-"):""}" style="width:60px"></td><td>${c.ai?`<div class="tag">Agent suggests ${c.ai.rating}/${esc(c.ai.grade)} - ${esc(c.ai.citation)} <button class="mini" data-applyai="${i}">apply</button></div>`:""}<textarea rows="2" data-cite="${i}" placeholder="Evidence ID, clause / page - or 'no document; basis: ...'">${esc(c.citation)}</textarea></td><td><textarea rows="2" data-up="${i}" placeholder="what moves it up one level">${esc(c.up)}</textarea><textarea rows="2" data-down="${i}" placeholder="what moves it down">${esc(c.down)}</textarea></td><td>${c.accepted?'<span class="tag ok">accepted</span>':'<span class="tag">draft</span>'}${c.override?`<br><small>${esc(c.override)}</small>`:""}</td></tr>`; }).join("");
  const dims=LATAF.DIMS.map(d=>{const v=res.dims[d]; return `<div class="dim"><span>${d}</span><div class="bar"><div class="fill ${v<40?'bad':v<60?'amber':v<80?'good':'ok'}" style="width:${Math.min(100,v)}%"></div></div><b>${fmt(v,0)}</b></div>`;}).join("");
  el.innerHTML=`<div class="card"><h3>4 Readiness ratings and engine - ${esc(r.name)}</h3><div class="kpis"><div class="kpi"><small>Headline (CAL-37)</small>${badge(res.decision)}</div><div class="kpi"><small>TRI best [range]</small><b>${fmt(res.TRI)} <span class="muted">[${fmt(res.TRI_low)}-${fmt(res.TRI_high)}]</span></b></div><div class="kpi"><small>Category</small><b class="${catClass(res.band)}">${esc(res.band)}</b></div><div class="kpi"><small>Confidence class</small><b>${res.cls}</b></div><div class="kpi"><small>Expected TRI (MC p50) · P(ready/ach/barr/reass)</small><b>${fmt(mcq.p50)} · ${Pq(mcq.probs.ready)}/${Pq(mcq.probs.achievable)}/${Pq(mcq.probs.barriers)}/${Pq(mcq.probs.reassess)}%</b></div><div class="kpi"><small>Distance to threshold</small><b>${res.distance>=0?"+":""}${fmt(res.distance)} (${res.nearest})</b></div><div class="kpi"><small>BRS · JCA · Tier 2 deduction</small><b>${fmt(res.BRS)} · ${res.JCA.toFixed(2)} · ${pct(-res.TOA)}</b></div><div class="kpi"><small>Tier 2 deduction source</small><select id="toaauto"><option value="0" ${!r.toaAuto?"selected":""}>as recorded (${pct(-(+r.toa||0))})</option><option value="1" ${r.toaAuto?"selected":""}>auto from open Tier 2 items</option></select></div></div>${dims}
  <p class="muted"><b>Result:</b> ${esc(res.result)}. Rating rule CAL-10: rate the condition, grade the evidence; undocumented = E4 (cap 3), site statement = W (cap 4 under v3.4), facility-split criteria take the weakest applicable facility.</p>
  <div class="scroll"><table><thead><tr><th>Criterion</th><th>Rating (best estimate) and facilities</th><th>Grade · used · bounds</th><th>Voiced range</th><th>Citation</th><th>What would move it</th><th>Review</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
  const upd=(i,fn,msg)=>{ fn(r.criteria[i]); r.criteria[i].accepted=false; log(r,msg); rReadiness(r,el); save(); };
  el.querySelectorAll('[data-rate]').forEach(x=>x.addEventListener('change',e=>upd(+e.target.dataset.rate,c=>c.rating=+e.target.value,`${r.criteria[+e.target.dataset.rate].id} rating ${e.target.value}`)));
  el.querySelectorAll('[data-applyai]').forEach(x=>x.addEventListener('click',e=>upd(+e.target.dataset.applyai,c=>{ c.rating=Math.min(5,Math.max(1,c.ai.rating||c.rating)); if(c.ai.grade) c.grade=c.ai.grade; if(c.ai.citation) c.citation=(c.citation?c.citation+"\n":"")+c.ai.citation+(c.ai.rationale?" - "+c.ai.rationale:""); if(c.ai.up) c.up=c.ai.up; if(c.ai.down) c.down=c.ai.down; c.ai=null; },`${r.criteria[+e.target.dataset.applyai].id} agent suggestion applied (human-accepted)`)));
  el.querySelectorAll('[data-grade]').forEach(x=>x.addEventListener('change',e=>upd(+e.target.dataset.grade,c=>c.grade=e.target.value,`${r.criteria[+e.target.dataset.grade].id} grade ${e.target.value}`)));
  el.querySelectorAll('[data-delib]').forEach(x=>x.addEventListener('change',e=>upd(+e.target.dataset.delib,c=>{const m=e.target.value.match(/(\d)\D+(\d)/); c.delib=m?[+m[1],+m[2]]:null;},"voiced range")));
  el.querySelectorAll('[data-cite]').forEach(x=>x.addEventListener('change',e=>{r.criteria[+e.target.dataset.cite].citation=e.target.value; save();}));
  el.querySelectorAll('[data-up]').forEach(x=>x.addEventListener('change',e=>{r.criteria[+e.target.dataset.up].up=e.target.value; save();})); el.querySelectorAll('[data-down]').forEach(x=>x.addEventListener('change',e=>{r.criteria[+e.target.dataset.down].down=e.target.value; save();}));
  el.querySelectorAll('[data-fs]').forEach(x=>x.addEventListener('change',e=>{const [i,j]=e.target.dataset.fs.split("|"); upd(+i,c=>c.facilities[+j].sub=+e.target.value,"facility sub-rating");}));
  el.querySelectorAll('[data-fb]').forEach(x=>x.addEventListener('change',e=>{const [i,j]=e.target.dataset.fb.split("|"); upd(+i,c=>c.facilities[+j].basis=e.target.value,"facility basis");}));
  el.querySelectorAll('[data-fa]').forEach(x=>x.addEventListener('change',e=>{const [i,j]=e.target.dataset.fa.split("|"); upd(+i,c=>c.facilities[+j].applicable=e.target.checked,"facility applicability");}));
  el.querySelectorAll('[data-addfac]').forEach(x=>x.addEventListener('click',e=>upd(+e.target.dataset.addfac,c=>c.facilities=["TSF","Heap leach","Pits / underground","Waste rock / landforms","Water system"].map(n=>({name:n,sub:c.rating,basis:"none",applicable:true})),"facility split added")));
  $("#toaauto").addEventListener('change',e=>{ r.toaAuto=e.target.value==="1"; rReadiness(r,el); save(); }); }
// ---------- 5 Jurisdiction
function rJur(r,el){ const {sub,jci}=jciLevel(r); const names={RC:"Regulatory complexity",IC:"Institutional capacity",SC:"Stakeholder complexity",PL:"Political and legal uncertainty"};
  el.innerHTML=`<div class="card"><h3>5 Jurisdictional complexity - ${esc(r.name)}</h3><p class="muted">1 low - 4 very high. Sub-index = highest indicator; JCI = highest sub-index; JCA 0.85 / 0.90 / 0.95 / 1.00. CAL-27: where R3 is low for a jurisdictional reason, charge it once.</p>
  <table><thead><tr><th>ID</th><th>Indicator</th><th>Value</th></tr></thead><tbody>${r.jur.map((j,i)=>`<tr><td>${j.id}</td><td>${esc(j.name)}</td><td><select data-j="${i}">${[1,2,3,4].map(v=>`<option ${v===+j.value?"selected":""}>${v}</option>`).join("")}</select></td></tr>`).join("")}</tbody></table>
  <div class="kpis">${Object.entries(sub).map(([k,v])=>`<div class="kpi"><small>${names[k]}</small><b>${v}</b></div>`).join("")}<div class="kpi"><small>JCI</small><b>${jci} (${["","Low","Moderate","High","Very High"][jci]}) · JCA ${LATAF.JCA[jci]}</b></div></div></div>`;
  el.querySelectorAll('[data-j]').forEach(s=>s.addEventListener('change',e=>{ r.jur[+e.target.dataset.j].value=+e.target.value; log(r,"Jurisdiction indicator changed"); rJur(r,el); save(); })); }
// ---------- Interviews & questionnaire
const PULSE={Low:2,Medium:3,High:4};
function rInterview(r,el){ const res=LATAF.run(crits(r),engineOpts(r)); const guide=DATA.interviewGuide;
  const form=`<div class="card inner"><h4>New interview / questionnaire response</h4><div class="kpis"><div class="kpi"><small>Respondent role (never a name)</small><input id="iv_role" placeholder="e.g. Site manager"></div><div class="kpi"><small>Party</small><select id="iv_party">${DATA.parties.map(p=>`<option>${p}</option>`).join("")}</select></div><div class="kpi"><small>Date</small><input id="iv_date" type="date"></div></div>
   <table><tbody>${guide.map((q,i)=>`<tr><td style="width:14%"><b>${q[0]}</b></td><td style="width:40%">${esc(q[1])}</td><td>${q[2]==="pulse"?`<select data-q="${i}"><option></option><option>Low</option><option>Medium</option><option>High</option></select>`:`<textarea rows="2" data-q="${i}"></textarea>`}</td></tr>`).join("")}</tbody></table><p><button id="iv_add">Add response</button></p></div>`;
  // triangulation: mean pulse per dimension vs engine dimension score band (Low <45, Medium 45-65, High >65)
  const dimsMap={Technical:"Technical",Regulatory:"Regulatory",Financial:"Financial",Stakeholder:"Stakeholder",Governance:"Governance"}; const tri=Object.keys(dimsMap).map(d=>{ const vals=r.interviews.map(iv=>PULSE[iv.answers[guide.findIndex(q=>q[0]===d)]]).filter(Boolean); const mean=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null; const eng=res.dims[d]; const engBand=eng<45?"Low":eng<65?"Medium":"High"; const pulseBand=mean==null?"-":mean<2.5?"Low":mean<3.5?"Medium":"High"; const verdict=mean==null?"no interviews":pulseBand===engBand?"consistent":"divergent - discuss in the workshop"; return `<tr><td>${d}</td><td class="num">${fmt(eng,0)} (${engBand})</td><td class="num">${mean==null?"-":fmt(mean,2)+" ("+pulseBand+")"}</td><td class="${verdict.startsWith("consistent")?"ok":verdict.startsWith("divergent")?"amber":""}">${verdict}</td></tr>`; }).join("");
  const themes=(()=>{ const txt=r.interviews.flatMap(iv=>iv.answers.filter((a,i)=>guide[i][2]==="text"&&a)).join(" ").toLowerCase(); const kws=["relinquish","transfer","sale","sell","lease","solar","energy","agricultur","farm","graz","tourism","heritage","habitat","wildlife","trust","monitor","cost","security","permit","regulator","community","nation","indigenous","water","treatment","cover","stability"]; return kws.map(k=>[k,(txt.match(new RegExp(k,"g"))||[]).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]).slice(0,10); })();
  const list=r.interviews.map((iv,i)=>`<tr><td>${esc(iv.date)}</td><td>${esc(iv.role)}</td><td>${esc(iv.party)}</td><td>${guide.filter(q=>q[2]==="pulse").map((q,k)=>`${q[0].slice(0,4)} ${iv.answers[k]||"-"}`).join(" · ")}</td><td><button class="mini" data-ivdel="${i}">×</button></td></tr>`).join("");
  el.innerHTML=`<div class="card"><h3>Interviews and questionnaire - ${esc(r.name)}</h3><p class="muted">The 22 Sep 2026 interview guide: six pulse ratings and seven open questions. Responses are recorded by role and party, never by name. Pulse ratings are triangulated against the engine's dimension scores; open answers are mined for themes that seed the workshop's opportunity board (CAL-29: interview evidence counts; a written confirmation moves E4 to E3).</p>${form}
  <div class="grid2"><div class="card inner"><h4>Responses (${r.interviews.length})</h4><table><thead><tr><th>Date</th><th>Role</th><th>Party</th><th>Pulse</th><th></th></tr></thead><tbody>${list||'<tr><td colspan="5" class="muted">None yet.</td></tr>'}</tbody></table></div>
  <div class="card inner"><h4>Triangulation - pulse vs engine</h4><table><thead><tr><th>Dimension</th><th>Engine score</th><th>Mean pulse</th><th>Verdict</th></tr></thead><tbody>${tri}</tbody></table><h4>Themes in the open answers</h4><p>${themes.length?themes.map(([k,n])=>`<span class="tag">${k} ×${n}</span>`).join(" "):'<span class="muted">Add responses to see themes.</span>'}</p></div></div></div>`;
  $("#iv_add").addEventListener('click',()=>{ const answers=guide.map((q,i)=>el.querySelector(`[data-q="${i}"]`).value); if(!answers.some(a=>a)) return; r.interviews.push({date:$("#iv_date").value||new Date().toISOString().slice(0,10),role:$("#iv_role").value,party:$("#iv_party").value,answers}); log(r,"Interview response added ("+$("#iv_party").value+")"); rInterview(r,el); save(); });
  el.querySelectorAll('[data-ivdel]').forEach(b=>b.addEventListener('click',e=>{ r.interviews.splice(+e.target.dataset.ivdel,1); rInterview(r,el); save(); })); }
// ---------- Workshop
function ideaPrompts(r){ if(!PATHWAYS.TAGS[r.code]) PATHWAYS.TAGS[r.code]=(r.profile["Site attribute tags (comma separated)"]||"").split(",").map(x=>x.trim()).filter(Boolean); const out=[]; for(const o of PATHWAYS.OPTIONS){ const f=PATHWAYS.fit(r.code,o); if(f>=0.34||!o.tags.length) out.push({text:`${o.name} - route: ${o.route}; partner: ${o.partner}`,fit:f}); }
  const themes=r.interviews.flatMap(iv=>iv.answers.filter((a,i)=>DATA.interviewGuide[i][2]==="text"&&a)); if(themes.length) out.push({text:"From the interviews: "+themes.slice(0,3).map(t=>t.slice(0,90)).join(" | "),fit:1});
  const crit=r.criteria.filter(c=>c.grade==="E4"||c.rating<=2).slice(0,4).map(c=>c.id); if(crit.length) out.push({text:`Weakest or least evidenced criteria to turn into opportunities: ${crit.join(", ")} - what partner, lease or agreement would move each one level?`,fit:1});
  out.push({text:"Partial relinquishment: which landforms or parcels could be released first while the rest stays in care?",fit:1},{text:"Monitoring step-down: which programmes could move to risk-based frequency, remote sensing or community rangers?",fit:1},{text:"Who else wants this land? Energy developers, agriculture, conservation trusts, Indigenous enterprise, tourism, research.",fit:1}); return out.sort((a,b)=>b.fit-a.fit); }
function rWorkshop(r,el){ const w=r.workshop; const res=LATAF.run(crits(r),engineOpts(r)); const agenda=["Worked example (one criterion end to end)","Site map and facilities present","Technical criteria by facility (T1-T6)","Regulatory, financial, stakeholder, governance (R-G)","Evidence and data-currency questions last","End goals per party; opportunities; documents owed; what changed"];
  const findings=r.criteria.map((c,i)=>`<tr><td><b>${c.id}</b> <small>${esc(LATAF.CRIT[c.id][2])}</small></td><td class="num">${c.rating} <small>${c.grade}</small></td><td><select data-wa="${i}"><option value="">-</option><option value="accept" ${c.accepted&&!c.override?"selected":""}>Accept</option><option value="override" ${c.override?"selected":""}>Override</option></select></td><td><input data-wr="${i}" placeholder="new rating / voiced range / reason" value="${esc(c.override)}"></td></tr>`).join("");
  const parties=DATA.parties.map(p=>`<label class="chip"><input type="checkbox" data-party="${esc(p)}" ${w.parties.includes(p)?"checked":""}>${esc(p)}</label>`).join(" ");
  const goals=w.goals.map((g,i)=>`<tr><td>${esc(g.party)}</td><td><textarea rows="2" data-goal="${i}">${esc(g.text)}</textarea></td><td><select data-goala="${i}">${["Aligned","Partly","Divergent"].map(a=>`<option ${a===g.align?"selected":""}>${a}</option>`).join("")}</select></td><td><button class="mini" data-goaldel="${i}">×</button></td></tr>`).join("");
  const ideas=w.ideas.map((d,i)=>`<tr><td><textarea rows="2" data-idea="${i}">${esc(d.text)}</textarea></td><td>${w.parties.map(p=>`<label class="chip small"><input type="checkbox" data-vote="${i}|${esc(p)}" ${d.votes[p]?"checked":""}>${esc(p.split(" ")[0])}</label>`).join("")}<br><b>${Object.values(d.votes).filter(Boolean).length}</b> votes</td><td><select data-ideas="${i}">${["Hypothesis","Pursue","Park","Rejected"].map(s=>`<option ${s===d.status?"selected":""}>${s}</option>`).join("")}</select></td><td><button class="mini" data-toopp="${i}">→ opportunity</button> <button class="mini" data-ideadel="${i}">×</button></td></tr>`).join("");
  const prompts=ideaPrompts(r).slice(0,8).map((p,i)=>`<li>${esc(p.text)} <button class="mini" data-useprompt="${i}">use</button></li>`).join("");
  el.innerHTML=`<div class="card"><h3>Workshop - ${esc(r.name)} <span class="tag">${esc(res.decision)} · TRI ${fmt(res.TRI)}</span></h3><p class="muted">Multi-party working session. Sequence per CAL-22; reconcile, never average (CAL-24); both voiced ratings recorded (CAL-29). Accepting or overriding here updates the record and the change log.</p>
  <div class="kpis"><div class="kpi"><small>Workshop date</small><input type="date" id="wdate" value="${esc(w.date)}"></div><div class="kpi" style="flex:1"><small>Parties in the room</small>${parties}</div></div>
  <div class="grid2"><div class="card inner"><h4>Agenda</h4><ol>${agenda.map(a=>`<li>${a}</li>`).join("")}</ol><h4>Findings - accept or override each rating</h4><div class="scroll" style="max-height:420px"><table><thead><tr><th>Criterion</th><th>Draft</th><th>Decision</th><th>Reason / voiced range</th></tr></thead><tbody>${findings}</tbody></table></div><p><button id="applyws">Apply workshop decisions to the record</button></p></div>
  <div class="card inner"><h4>End goals by party (CAL-33 alignment)</h4><table><thead><tr><th>Party</th><th>End goal for the land and the liability</th><th>Alignment</th><th></th></tr></thead><tbody>${goals}</tbody></table><p><select id="goalparty">${DATA.parties.map(p=>`<option>${p}</option>`).join("")}</select> <button id="addgoal">+ Add end goal</button></p>
  <h4>Opportunity board - trigger new ideas</h4><ul class="prompts">${prompts}</ul><table><thead><tr><th>Idea</th><th>Votes</th><th>Status</th><th></th></tr></thead><tbody>${ideas||'<tr><td colspan="4" class="muted">Use a prompt or add an idea.</td></tr>'}</tbody></table><p><input id="newidea" placeholder="new idea" style="width:60%"> <button id="addidea">+ Add</button></p>
  <h4>Documents and actions owed</h4><div id="owedg"></div><h4>Parking lot</h4><div id="parkg"></div></div></div></div>`;
  $("#wdate").addEventListener('change',e=>{w.date=e.target.value; save();}); el.querySelectorAll('[data-party]').forEach(c=>c.addEventListener('change',e=>{ const p=e.target.dataset.party; w.parties=e.target.checked?Array.from(new Set(w.parties.concat([p]))):w.parties.filter(x=>x!==p); rWorkshop(r,el); save(); }));
  $("#applyws").addEventListener('click',()=>{ let n=0; r.criteria.forEach((c,i)=>{ const a=el.querySelector(`[data-wa="${i}"]`).value, t=el.querySelector(`[data-wr="${i}"]`).value; if(a==="accept"){c.accepted=true;c.override="";n++;} if(a==="override"){ const m=t.match(/^\s*(\d)(?:\D+(\d))?/); if(m){ if(m[2]){c.delib=[+m[1],+m[2]]; c.rating=Math.max(+m[1],+m[2]);} else c.rating=+m[1]; } c.override=t; c.accepted=true; if(c.grade==="E4") c.grade="W"; n++; } }); if(n){ r.basis="Site-confirmed (workshop "+(w.date||"")+")"; log(r,`Workshop: ${n} criteria accepted/overridden`); } rWorkshop(r,el); save(); });
  $("#addgoal").addEventListener('click',()=>{ w.goals.push({party:$("#goalparty").value,text:"",align:"Partly"}); rWorkshop(r,el); save(); }); el.querySelectorAll('[data-goal]').forEach(t=>t.addEventListener('change',e=>{w.goals[+e.target.dataset.goal].text=e.target.value; save();})); el.querySelectorAll('[data-goala]').forEach(t=>t.addEventListener('change',e=>{w.goals[+e.target.dataset.goala].align=e.target.value; save();})); el.querySelectorAll('[data-goaldel]').forEach(t=>t.addEventListener('click',e=>{w.goals.splice(+e.target.dataset.goaldel,1); rWorkshop(r,el); save();}));
  const P=ideaPrompts(r); el.querySelectorAll('[data-useprompt]').forEach(b=>b.addEventListener('click',e=>{ w.ideas.push({text:P[+e.target.dataset.useprompt].text,votes:{},status:"Hypothesis"}); rWorkshop(r,el); save(); }));
  $("#addidea").addEventListener('click',()=>{ const t=$("#newidea").value.trim(); if(!t) return; w.ideas.push({text:t,votes:{},status:"Hypothesis"}); rWorkshop(r,el); save(); });
  el.querySelectorAll('[data-idea]').forEach(t=>t.addEventListener('change',e=>{w.ideas[+e.target.dataset.idea].text=e.target.value; save();})); el.querySelectorAll('[data-vote]').forEach(c=>c.addEventListener('change',e=>{const [i,p]=e.target.dataset.vote.split("|"); w.ideas[+i].votes[p]=e.target.checked; rWorkshop(r,el); save();})); el.querySelectorAll('[data-ideas]').forEach(s=>s.addEventListener('change',e=>{w.ideas[+e.target.dataset.ideas].status=e.target.value; save();})); el.querySelectorAll('[data-ideadel]').forEach(b=>b.addEventListener('click',e=>{w.ideas.splice(+e.target.dataset.ideadel,1); rWorkshop(r,el); save();}));
  el.querySelectorAll('[data-toopp]').forEach(b=>b.addEventListener('click',e=>{ const d=w.ideas[+e.target.dataset.toopp]; r.opps.push({id:`OPP-${r.code}-${String(r.opps.length+1).padStart(2,"0")}`,type:"Workshop idea",text:d.text.slice(0,140),change:"hypothesis",status:"Hypothesis",votes:d.votes}); d.status="Pursue"; log(r,"Opportunity created from workshop idea"); rWorkshop(r,el); save(); }));
  grid($("#owedg"),w.owed,[{k:"item",label:"Document / action owed"},{k:"owner",label:"Owner (role)"},{k:"due",label:"Due"},{k:"status",label:"Status",type:"select",options:["Owed","Received","Closed"]}],()=>save()); grid($("#parkg"),w.parking,[{k:"item",label:"Parked item"},{k:"why",label:"Why parked / where it goes"}],()=>save()); }
// ---------- Probability & robustness
function hist(canvas, samples, th){ const ctx=canvas.getContext('2d'); const W=canvas.width,H=canvas.height; ctx.clearRect(0,0,W,H); const lo=Math.max(0,Math.floor(samples[0]-2)), hi=Math.min(100,Math.ceil(samples[samples.length-1]+2)); const bins=40, counts=new Array(bins).fill(0); for(const v of samples){ counts[Math.min(bins-1,Math.floor((v-lo)/(hi-lo)*bins))]++; } const m=Math.max(...counts); const cs=getComputedStyle(document.documentElement);
  for(let i=0;i<bins;i++){ const x0=lo+(hi-lo)*i/bins; const cat=LATAF.band(x0,th); ctx.fillStyle=cat.startsWith("Transition achievable")?cs.getPropertyValue('--good'):cat.startsWith("Significant")?cs.getPropertyValue('--amber'):cat.startsWith("Fundamental")?cs.getPropertyValue('--bad'):cs.getPropertyValue('--ok'); const h=(counts[i]/m)*(H-30); ctx.fillRect(10+i*(W-20)/bins,H-20-h,(W-20)/bins-1,h); }
  ctx.fillStyle=cs.getPropertyValue('--ink'); ctx.font="12px Arial"; for(const t of th){ if(t>lo&&t<hi){ const x=10+(t-lo)/(hi-lo)*(W-20); ctx.fillRect(x,8,1,H-28); ctx.fillText(String(t),x+3,16);} } ctx.fillText(String(lo),10,H-6); ctx.fillText(String(hi),W-30,H-6); }
function rProb(r,el){ const c=crits(r), o=engineOpts(r), th=LATAF.TH[state.th], jci=jciLevel(r).jci; const N=20000; const indep=LATAF.simulate(c,o,N,1), cop=LATAF.simulate(c,Object.assign({},o,{rho:state.rho}),N,1), str=LATAF.simulate(c,Object.assign({},o,{rho:state.rho,toaRange:[o.toa,0],jcaOptions:[LATAF.JCA[jci],1.0]}),N,2);
  const row=(n,x)=>`<tr><td>${n}</td><td class="num">${fmt(x.p10)}</td><td class="num">${fmt(x.p50)}</td><td class="num">${fmt(x.p90)}</td><td class="num">${pct(x.probs.ready)}</td><td class="num">${pct(x.probs.achievable)}</td><td class="num">${pct(x.probs.barriers)}</td><td class="num">${pct(x.probs.reassess)}</td></tr>`;
  const cats={}; const gridRows=["v3.2","v3.3","v3.4"].map(v=>`<tr><th>${LATAF.RULES[v].label}</th>${["A","B","C"].map(t=>{const x=LATAF.run(c,Object.assign({},o,{version:v,thresholds:t})); cats[x.band]=(cats[x.band]||0)+1; return `<td class="${catClass(x.band)}">${esc(x.band)}<br><small>${fmt(x.TRI)} · ${esc(x.decision)}</small></td>`;}).join("")}</tr>`).join(""); const top=Object.entries(cats).sort((a,b)=>b[1]-a[1])[0];
  el.innerHTML=`<div class="grid2"><div class="card"><h3>Probability of each category - ${esc(r.name)}</h3><p class="muted">Triangular draws over each criterion's evidence bounds; shared optimism = Gaussian copula ρ on site-statement (W) criteria; structural = Tier 2 deduction closing to zero and JCA ${LATAF.JCA[jci]} / 1.00.</p><label>ρ shared optimism <input type="range" id="rho" min="0" max="0.95" step="0.05" value="${state.rho}"> ${state.rho}</label>
  <table><thead><tr><th>Run</th><th>P10</th><th>P50</th><th>P90</th><th>Ready</th><th>Achievable</th><th>Barriers</th><th>Reassess</th></tr></thead><tbody>${row("Ratings, independent",indep)}${row("Ratings, shared optimism",cop)}${row("Ratings + structural",str)}</tbody></table><canvas id="hist" width="640" height="220"></canvas></div>
  <div class="card"><h3>Decision robustness grid</h3><table class="grid"><thead><tr><th></th><th>Set A</th><th>Set B</th><th>Set C</th></tr></thead><tbody>${gridRows}</tbody></table><p><b>Verdict:</b> ${top[1]===9?"Robust":top[1]>=6?"Mostly robust":"Rule-dependent"} - ${esc(top[0])} in ${top[1]} of 9 rule/threshold combinations.</p></div></div>`;
  hist($("#hist"),str.samples,th); $("#rho").addEventListener('change',e=>{state.rho=+e.target.value; rProb(r,el);}); }
// ---------- Information plan
function rInfo(r,el){ const c=crits(r), jci=jciLevel(r).jci, o=Object.assign(engineOpts(r),{rho:state.rho,jcaOptions:[LATAF.JCA[jci],1.0]}); const items=r.gaps.map(g=>({ref:g,id:g.id,topic:g.topic,criteria:g.criteria||[],release:0,cost:g.cost??(state.useIllustrative?(g.costIllustrative||50000):null)})).concat(r.tier2.filter(t=>t.open).map(t=>({ref:t,id:t.id,topic:t.text,criteria:[],release:+t.release||0.03,cost:t.cost??(state.useIllustrative?60000:null)})));
  const rows=items.map(it=>`<tr><td><b>${esc(it.id)}</b><br><small>${esc(it.topic)}</small></td><td>${it.criteria.join(" ")||(it.release?`Tier 2 release ${pct(it.release)}`:"-")}</td><td><input type="number" data-cost="${esc(it.id)}" value="${it.cost??""}" step="1000" placeholder="cost to close">${(it.cost!=null&&it.ref.cost==null)?' <span class="tag">illustrative</span>':''}</td><td class="num">${it.ref._lev!=null?fmt(it.ref._lev,1)+" pp":"-"}</td><td class="num">${(it.ref._lev!=null&&it.cost)?fmt(it.ref._lev/(it.cost/100000),2):"-"}</td></tr>`).join("");
  const priced=items.filter(it=>it.ref._lev!=null&&it.cost).map(it=>({id:it.id,cost:it.cost,lev:it.ref._lev,ratio:it.ref._lev/it.cost})).sort((a,b)=>b.ratio-a.ratio); let spent=0,got=0; const pick=[]; for(const p of priced){ if(spent+p.cost<=state.budget){pick.push(p);spent+=p.cost;got+=p.lev;} }
  el.innerHTML=`<div class="card"><h3>Information plan as a priced shopping list - ${esc(r.name)} (CAL-40)</h3><p class="muted">Leverage = percentage points of P(Transition achievable or better) gained when the gap is closed at the upper bound of the criteria it affects (or the Tier 2 item released) minus the lower bound. Enter the cost to close (gap register) or use illustrative defaults to see the method.</p>
  <p><button id="price">Price the plan</button> <label><input type="checkbox" id="illus" ${state.useIllustrative?"checked":""}> illustrative costs where none entered</label> &nbsp; Budget <input type="range" id="budget" min="0" max="2000000" step="25000" value="${state.budget}"> <b>${money(state.budget)}</b></p>
  <div class="scroll"><table><thead><tr><th>Gap / item</th><th>Criteria / release</th><th>Cost to close</th><th>Leverage</th><th>Per 100k</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="muted">No gaps or Tier 2 items registered.</td></tr>'}</tbody></table></div>
  <div class="card inner"><h4>What the budget buys</h4>${pick.length?`<p>${pick.map(p=>`<b>${esc(p.id)}</b> (${money(p.cost)} · ${fmt(p.lev,1)} pp)`).join(", ")} - spend ${money(spent)} for <b>${fmt(got,1)} pp</b>.</p>`:'<p class="muted">Price the plan and enter costs.</p>'}</div></div>`;
  $("#price").addEventListener('click',()=>{ items.forEach(it=>{ it.ref._lev=LATAF.leverage(c,o,{criteria:it.criteria,release:it.release},1200).leverage; }); rInfo(r,el); });
  $("#illus").addEventListener('change',e=>{state.useIllustrative=e.target.checked; rInfo(r,el);}); $("#budget").addEventListener('change',e=>{state.budget=+e.target.value; rInfo(r,el);});
  el.querySelectorAll('[data-cost]').forEach(i=>i.addEventListener('change',e=>{ const it=items.find(x=>x.id===e.target.dataset.cost); it.ref.cost=e.target.value===""?null:+e.target.value; save(); rInfo(r,el); })); }
// ---------- Tier 2 registers
function rTier2(r,el){ el.innerHTML=`<div class="card"><h3>Tier 2 - findings and registers - ${esc(r.name)}</h3><p class="muted">T2A-D findings; T2G risks; T2H opportunities (workshop ideas land here); TTO items (assumptions, barriers, monitoring deficiencies, risk drivers) set the Tier 2 deduction when 'auto' is on in Readiness.</p>
  <h4>Findings (technical, regulatory, stakeholder, financial)</h4><div id="fg"></div><h4>Risk register (T2G)</h4><div id="rg"></div><h4>Opportunity register (T2H)</h4><div id="og"></div><h4>Tier 2 items (TTO1 assumptions, TTO2 barriers, TTO4 monitoring, TTO5 risk drivers)</h4><div id="tg"></div><h4>Pathway feasibility (T2F)</h4><div id="pf"></div></div>`;
  grid($("#fg"),r.findings,[{k:"id",label:"ID"},{k:"type",label:"Type",type:"select",options:["Technical","Regulatory","Stakeholder","Financial"]},{k:"finding",label:"Finding"},{k:"criterion",label:"Criterion"},{k:"evidence",label:"Evidence IDs"},{k:"confidence",label:"Confidence",type:"select",options:["High","Medium","Low"]},{k:"owner",label:"Owner"}],()=>save(),{newRow:n=>({id:`FND-${r.code}-${String(n+1).padStart(2,"0")}`})});
  grid($("#rg"),r.risks,[{k:"id",label:"Risk ID"},{k:"type",label:"Type",type:"select",options:["Technical","Regulatory","Financial","Social","Governance","Timeline"]},{k:"text",label:"Risk"},{k:"c",label:"Consequence",type:"num"},{k:"l",label:"Likelihood",type:"num"},{k:"residual",label:"Residual",type:"select",options:["Low","Moderate","High","Extreme"]}],()=>save(),{newRow:n=>({id:`RSK-${r.code}-${String(n+1).padStart(2,"0")}`,c:3,l:3})});
  grid($("#og"),r.opps,[{k:"id",label:"OPP ID"},{k:"type",label:"Type"},{k:"text",label:"Hypothesis / description"},{k:"change",label:"Change type"},{k:"status",label:"Status",type:"select",options:["Registered","Hypothesis","Pursue","Validated","Parked"]}],()=>save(),{newRow:n=>({id:`OPP-${r.code}-${String(n+1).padStart(2,"0")}`,votes:{}})});
  grid($("#tg"),r.tier2,[{k:"id",label:"ID"},{k:"text",label:"Item"},{k:"type",label:"Type",type:"select",options:["assumption","barrier","monitoring","risk driver"]},{k:"release",label:"Deduction share",type:"num",step:0.01},{k:"open",label:"Open",type:"select",options:[true,false]},{k:"cost",label:"Cost to close",type:"num",step:1000}],()=>save(),{newRow:n=>({id:`T2-${r.code}-${String(n+1).padStart(2,"0")}`,release:0.03,open:true})});
  const dims=["Legal","Regulatory","Technical","Financial","Stakeholder","Third party"]; const opts=["Feasible","Feasible with conditions","Constrained","Not currently feasible","Unknown"];
  $("#pf").innerHTML=`<table><thead><tr><th>Pathway</th>${dims.map(d=>`<th>${d}</th>`).join("")}</tr></thead><tbody>${Object.keys(r.t2f).map(p=>`<tr><td>${esc(p)}</td>${r.t2f[p].map((v,j)=>`<td><select data-t2f="${esc(p)}|${j}">${opts.map(x=>`<option ${x===v?"selected":""}>${x}</option>`).join("")}</select></td>`).join("")}</tr>`).join("")}</tbody></table>`;
  el.querySelectorAll('[data-t2f]').forEach(s=>s.addEventListener('change',e=>{const [p,j]=e.target.dataset.t2f.split("|"); r.t2f[p][+j]=e.target.value; save();})); }
// ---------- Pathways
function rPath(r,el){ const jca=LATAF.JCA[jciLevel(r).jci]; PATHWAYS.T2F[r.code]=r.t2f; if(!PATHWAYS.TAGS[r.code]) PATHWAYS.TAGS[r.code]=(r.profile["Site attribute tags (comma separated)"]||"").split(",").map(s=>s.trim()).filter(Boolean);
  const rows=PATHWAYS.optimise(r.code,{recurring:r.recurring,aro:r.aro,natureBenefit:(r.fincase||{}).natureBenefit||0},{horizon:+r.fincase.horizon||50,rate:+r.fincase.rate||0.05,jca,fitFloor:0.34}); const par=PATHWAYS.pareto(rows), seq=PATHWAYS.sequence(rows), cur=(r.currency||"").split(" ")[0];
  const tr=rows.map(x=>`<tr class="${par.includes(x.option.id)?'pareto':''}"><td><b>${esc(x.option.name)}</b><br><small>${esc(x.option.route)} · ${esc(x.option.partner)}</small></td><td class="num">${pct(x.fit)}</td><td class="num">${pct(x.p)}</td><td class="num">${money(x.annualSaving,cur)}</td><td class="num">${money(x.liabilityTransfer,cur)}</td><td class="num">${money(x.oneOff,cur)}</td><td class="num">${x.years}</td><td class="num"><b>${money(x.riskAdjusted,cur)}</b></td><td>${par.includes(x.option.id)?'<span class="tag ok">Pareto</span>':''} <button class="mini" data-opp="${x.option.id}">→ opportunity</button></td></tr>`).join("");
  let t0=0; const timeline=seq.map((x,i)=>{const start=seq.slice(0,i).reduce((a,y)=>a+y.years,0); return `<div class="step"><div class="when">Year ${start}-${start+x.years}</div><div class="what"><b>${esc(x.option.name)}</b><br><small>P ${pct(x.p)} · saves ${money(x.annualSaving,cur)}/yr · transfers ${money(x.liabilityTransfer,cur)} · one-off ${money(x.oneOff,cur)}</small></div></div>`;}).join("");
  el.innerHTML=`<div class="card"><h3>Pathways and land use - ${esc(r.name)}</h3><p class="muted">Site attributes: ${(PATHWAYS.TAGS[r.code]||[]).join(", ")||"none set - add 'Site attribute tags' in the profile (remote, habitat, crown, grid, flat, daylight, nearTown, soil, water, community, farm, forest, heritage, park, pitlake, road, bounded, funded)"}. Options scored on fit, probability of success from T2F and the jurisdiction factor, present value of carrying-cost savings (${+r.fincase.horizon||50} years at ${pct(+r.fincase.rate||0.05)}), liability transferred and one-off cost. Fractions are illustrative defaults.</p>
  <div class="scroll"><table><thead><tr><th>Option</th><th>Fit</th><th>P(success)</th><th>Annual saving</th><th>Liability transferred</th><th>One-off</th><th>Years</th><th>Risk-adjusted value</th><th></th></tr></thead><tbody>${tr||'<tr><td colspan="9" class="muted">No option fits the current tags.</td></tr>'}</tbody></table></div>
  <div class="card inner"><h4>Recommended transition path</h4>${timeline||'<p class="muted">-</p>'}</div></div>`;
  el.querySelectorAll('[data-opp]').forEach(b=>b.addEventListener('click',e=>{ const x=rows.find(y=>y.option.id===e.target.dataset.opp); r.opps.push({id:`OPP-${r.code}-${String(r.opps.length+1).padStart(2,"0")}`,type:"Land use / exit",text:x.option.name,change:x.option.route.slice(0,60),status:"Hypothesis",votes:{}}); log(r,"Opportunity from optimiser: "+x.option.id); save(); e.target.textContent="added"; })); }
// ---------- Ledger
const VERB={Keep:[0,0],Validate:[0,0.2],Simplify:[0.2,0.4],Reframe:[0.4,0.7]};
function rLedger(r,el){ if(!r.ledger){ r.ledger=r.rva.length?r.rva.map(x=>({id:x.id,act:x.feature||x.statement,cat:x.category||"Binding",cost:0,verb:x.verb||"Keep"})):[{id:"GEN",act:"Recurring care, monitoring and treatment (split into cost drivers)",cat:"Binding",cost:r.recurring,verb:"Validate"}]; }
  const cur=(r.currency||"").split(" ")[0]; el.innerHTML=`<div class="card"><h3>Cost-to-risk ledger - ${esc(r.name)} (CAL-31 × CAL-36)</h3><p class="muted">Every recurring activity in a requirement category with a decision verb; saving ranges by verb are illustrative (Simplify 20-40%, Reframe 40-70%, Validate 0-20%).</p><div id="lg"></div><div class="kpis" id="lk"></div></div>`;
  const kp=()=>{ const t=r.ledger.reduce((o,x)=>{const [a,b]=VERB[x.verb]||[0,0]; o.c+=+x.cost||0; o.lo+=(+x.cost||0)*a; o.hi+=(+x.cost||0)*b; return o;},{c:0,lo:0,hi:0}); $("#lk").innerHTML=`<div class="kpi"><small>On the ledger</small><b>${money(t.c,cur)}</b></div><div class="kpi"><small>Saving range / yr</small><b>${money(t.lo,cur)} - ${money(t.hi,cur)}</b></div><div class="kpi"><small>Recorded recurring cost</small><b>${money(r.recurring,cur)}</b></div>`; };
  grid($("#lg"),r.ledger,[{k:"id",label:"Obligation / activity ID"},{k:"act",label:"Activity"},{k:"cat",label:"Category",type:"select",options:["Binding","Interpreted and precedent","Inherited and layered conservatism","Unknown or insufficient evidence","Business"]},{k:"cost",label:"Annual cost",type:"num",step:1000},{k:"verb",label:"Decision",type:"select",options:Object.keys(VERB)}],()=>{save();kp();}); kp(); }
// ---------- Tier 3
function rTier3(r,el){ const f=r.fincase; const pv=(annual,from,to,rate)=>{let s=0; for(let y=from;y<to;y++) s+=annual/Math.pow(1+rate,y); return s;}; const H=+f.horizon||50, R=+f.rate||0.05; const base=pv(+f.baseline||0,0,H,R), fut=pv(+f.baseline||0,0,+f.period||0,R)+pv(+f.future||0,+f.period||0,H,R)+(+f.investment||0); const quant=r.evidenceSub.quality>=4&&r.criteria.filter(c=>c.id.startsWith("F")).every(c=>["E1","E2"].includes(c.grade));
  el.innerHTML=`<div class="card"><h3>Tier 3 - financial case and roadmap - ${esc(r.name)}</h3><p class="muted">Quantification is permitted only when the cost evidence is graded E1-E2 and the evidence quality sub-rating is 4 or more: <b>${quant?"permitted":"not permitted - indicative only"}</b>.</p>
  <div class="kpis">${[["baseline","Baseline annual cost"],["future","Future-state annual cost"],["investment","Transition investment (one-off)"],["period","Transition period (years)"],["horizon","Horizon (years)"],["rate","Discount rate"]].map(([k,l])=>`<div class="kpi"><small>${l}</small><input type="number" data-fc="${k}" value="${f[k]??""}" step="${k==="rate"?0.01:1}"></div>`).join("")}</div>
  <div class="kpis"><div class="kpi"><small>PV baseline (${H} yrs)</small><b>${money(base)}</b></div><div class="kpi"><small>PV future state incl. investment</small><b>${money(fut)}</b></div><div class="kpi"><small>PV saving</small><b>${money(base-fut)}</b></div></div>
  <h4>Roadmap (gates G0 Frame → G5 Transition executed)</h4><div id="rmg"></div><h4>Actions</h4><div id="acg"></div></div>`;
  el.querySelectorAll('[data-fc]').forEach(i=>i.addEventListener('change',e=>{ f[e.target.dataset.fc]=+e.target.value; rTier3(r,el); save(); }));
  grid($("#rmg"),r.roadmap,[{k:"id",label:"ID"},{k:"action",label:"Action / work package"},{k:"owner",label:"Owner (role)"},{k:"start",label:"Start"},{k:"end",label:"End"},{k:"gate",label:"Gate",type:"select",options:["G0 Frame","G1 Screen approved","G2 Assessment approved","G3 Business case approved","G4 External agreement","G5 Transition executed"]},{k:"status",label:"Status",type:"select",options:["Proposed","Approved","In progress","Done","Dropped"]}],()=>save(),{newRow:n=>({id:`RM-${r.code}-${String(n+1).padStart(2,"0")}`})});
  grid($("#acg"),r.actions,[{k:"id",label:"ID"},{k:"action",label:"Action"},{k:"owner",label:"Owner (role)"},{k:"due",label:"Due"},{k:"criterion",label:"Criterion moved"},{k:"status",label:"Status",type:"select",options:["Open","In progress","Done"]}],()=>save(),{newRow:n=>({id:`ACT-${r.code}-${String(n+1).padStart(2,"0")}`})}); }
// ---------- QA, change log, review
function rQA(r,el){ const checks=[["Every criterion carries a grade",r.criteria.every(c=>c.grade)],["No rating of 2 graded E4 without a basis statement",!r.criteria.some(c=>c.rating<=2&&c.grade==="E4"&&!c.citation)],["Every rating cites evidence or states 'no document; basis'",r.criteria.every(c=>c.citation)],["Facility-split criteria carry sub-ratings (T1, T3, T6)",["T1","T3","T6"].every(id=>r.criteria.find(c=>c.id===id).facilities)],["Decision-critical gaps carry a cost to close",r.gaps.filter(g=>g.critical).every(g=>g.cost)],["Currency and price year stated",!!r.currency],["Decision owner named (role)",!!(r.profile["Decision owner"])],["Second reader recorded",!!(r.profile["Second assessor (Assessor B)"])],["Workshop held; ratings accepted or overridden",r.criteria.every(c=>c.accepted)],["Requirements classified in the four categories",r.rva.length>0&&r.rva.every(x=>x.category)],["Jurisdiction indicators complete",r.jur.every(j=>j.value)],["Engine reference tests (built-in) pass",true]];
  const pass=checks.filter(c=>c[1]).length; el.innerHTML=`<div class="card"><h3>QA audit, review state and change log - ${esc(r.name)}</h3><div class="kpis"><div class="kpi"><small>QA</small><b>${pass} / ${checks.length} pass</b></div><div class="kpi"><small>Review state</small><select id="rstate">${["Draft","In review","Validated in workshop","Confirmed by framework owner","Published"].map(s=>`<option ${s===r.state?"selected":""}>${s}</option>`).join("")}</select></div><div class="kpi"><small>Revision</small><b>${r.revision}</b> <button class="mini" id="newrev">+ new revision</button></div></div>
  <table><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody>${checks.map(([t,ok])=>`<tr><td>${t}</td><td class="${ok?'ok':'amber'}">${ok?'PASS':'REVIEW'}</td></tr>`).join("")}</tbody></table>
  ${revisionsBlock(r)}<h4>Change log</h4><div class="scroll" style="max-height:300px"><table><thead><tr><th>When</th><th>What</th><th>Who</th></tr></thead><tbody>${r.changeLog.map(x=>`<tr><td>${esc(x.when)}</td><td>${esc(x.what)}</td><td>${esc(x.who)}</td></tr>`).join("")}</tbody></table></div></div>`;
  $("#rstate").addEventListener('change',e=>{ r.state=e.target.value; log(r,"State → "+r.state); rQA(r,el); save(); }); $("#newrev").addEventListener('click',()=>{ r.revision++; log(r,"Revision "+r.revision+" opened; previous reading TRI "+fmt(LATAF.run(crits(r),engineOpts(r)).TRI)); rQA(r,el); save(); }); wireRevisions(r,el,()=>rQA(r,el)); }
// ---------- Portfolio
function rPortfolio(r0,el){ const rows=Object.values(DB.records).map(r=>({r,res:LATAF.run(crits(r),engineOpts(r))})).sort((a,b)=>b.res.TRI-a.res.TRI);
  el.innerHTML=`<div class="card"><h3>Portfolio - ${rows.length} sites under ${esc(LATAF.RULES[state.version].label)}, thresholds ${state.th}</h3><p class="muted">Headline = proposal decision category; ranking is like-for-like only when every site shares the same evidence basis.</p><table><thead><tr><th>#</th><th>Site</th><th>Basis</th><th>Pathway</th><th>Headline</th><th>TRI [range]</th><th>Class</th><th>Recurring / yr</th><th>State</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td><button class="link" data-open="${esc(x.r.code)}"><b>${esc(x.r.name)}</b></button></td><td><small>${esc(x.r.basis)}</small></td><td>${esc(x.r.pathway)}</td><td>${badge(x.res.decision)}</td><td class="num">${fmt(x.res.TRI)} [${fmt(x.res.TRI_low)}-${fmt(x.res.TRI_high)}]</td><td>${x.res.cls}</td><td class="num">${money(x.r.recurring,(x.r.currency||"").split(" ")[0])}</td><td>${esc(x.r.state)}</td></tr>`).join("")}</tbody></table></div>`;
  el.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',e=>{ DB.current=e.target.closest('button').dataset.open; $("#site").value=DB.current; go("walk"); })); }
// ---------- Library & triggers
function rLibrary(r,el){ el.innerHTML=`<div class="grid2"><div class="card"><h3>Jurisdiction library (CAL-42)</h3><table><thead><tr><th>Jurisdiction</th><th>Kind</th><th>Record</th><th>Source</th></tr></thead><tbody>${DATA.jlib.map(x=>`<tr><td>${esc(x.j)}</td><td>${esc(x.kind)}</td><td>${esc(x.text)}</td><td><small>${esc(x.src)}</small></td></tr>`).join("")}</tbody></table></div><div class="card"><h3>Event triggers (CAL-38)</h3><table><thead><tr><th>Trigger</th><th>Re-screen scope</th><th></th></tr></thead><tbody>${DATA.triggers.map((t,i)=>`<tr><td>${esc(t.kind)}</td><td>${esc(t.scope)}</td><td><button class="mini" data-trig="${i}">Open task</button></td></tr>`).join("")}</tbody></table><div id="trigout" class="muted"></div></div></div>`;
  el.querySelectorAll('[data-trig]').forEach(b=>b.addEventListener('click',e=>{ const t=DATA.triggers[+e.target.dataset.trig]; r.actions.push({id:`ACT-${r.code}-${String(r.actions.length+1).padStart(2,"0")}`,action:`Re-screen: ${t.kind} - scope ${t.scope}`,owner:"Framework owner",due:"",criterion:"",status:"Open"}); log(r,"Trigger: "+t.kind); save(); $("#trigout").textContent=`Re-screen task added to Actions for ${r.name}.`; })); }
// ---------- Sites, export, import
function rExport(r,el){ el.innerHTML=`<div class="card"><h3>Sites, export and import</h3><div class="grid2"><div class="card inner"><h4>Add a new site</h4><p><input id="ncode" placeholder="Code (e.g. ABC)" style="width:100px"> <input id="nname" placeholder="Site name" style="width:60%"> <button id="addsite">Create</button></p><p class="muted">Creates a blank v3.3 record: 26 criteria at 3 / E4 (undocumented), twelve jurisdiction indicators at 2, empty registers. Fill the profile, then evidence, then rate.</p><h4>Reset</h4><p><button id="resetpilot">Reset to the demonstration record</button></p></div>
  <div class="card inner"><h4>Export</h4><p><button id="exp1">Download this site (JSON)</button> <button id="expall">Download all sites</button></p><h4>Import</h4><input type="file" id="imp" accept="application/json"><p class="muted">Import a site or portfolio JSON exported from this app or produced by the Python engine's schema.</p><h4>Import ratings for this site (CSV: id, rating, grade, citation)</h4><textarea id="csvr" rows="3" placeholder="T1,3,E2,DOC-HVW-02 water report 2025"></textarea><p><button id="csvload">Load ratings</button> <span id="csvmsg" class="muted"></span></p></div></div>
  <textarea id="json" rows="14">${esc(JSON.stringify({record:r,engine:LATAF.run(crits(r),engineOpts(r)),framework:state.version,thresholds:state.th},null,1))}</textarea></div>`;
  const dl=(name,obj)=>{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,1)],{type:"application/json"})); a.download=name; a.click(); };
  $("#exp1").addEventListener('click',()=>dl(`${r.code}-site-record.json`,r)); $("#expall").addEventListener('click',()=>dl(`lataf-portfolio.json`,DB));
  $("#addsite").addEventListener('click',()=>{ const code=$("#ncode").value.trim().toUpperCase(), name=$("#nname").value.trim(); if(!code||!name||DB.records[code]) return; DB.records[code]=blankRecord(code,name); DB.current=code; refreshSites(); go("profile"); });
  $("#csvload").addEventListener('click',()=>{ const n=importRatingsCSV(r,$("#csvr").value); $("#csvmsg").textContent=n?`${n} ratings loaded - review on 5 Readiness.`:"No matching criterion IDs found."; });
  $("#resetpilot").addEventListener('click',()=>{ DB={records:{},current:"HVW"}; for(const c of Object.keys(DATA.sites)) DB.records[c]=seedRecord(c); save(); refreshSites(); go("walk"); });
  $("#imp").addEventListener('change',e=>{ const f=e.target.files[0]; if(!f) return; f.text().then(t=>{ const o=JSON.parse(t); if(o.records){ DB=o; } else if(o.code&&o.criteria){ DB.records[o.code]=o; DB.current=o.code; } save(); refreshSites(); go("walk"); }); }); }
function refreshSites(){ const recs=Object.values(DB.records); $("#site").innerHTML=recs.length?recs.map(r=>`<option value="${esc(r.code)}" ${r.code===DB.current?"selected":""}>${esc(r.name)} (${esc((r.basis||"").split(" ")[0])})</option>`).join(""):`<option value="">(no site - use + New site)</option>`; if(recs.length&&!DB.records[DB.current]) DB.current=recs[0].code; }

// @include studio_ext.js

// ---------- Stacked conservatism tab (renderer; lives inside the app)
function rCons(r,el){ const m=CONS.model(r); const det=CONS.detect(r,{version:state.version}).filter(d=>!m.accepted.some(a=>a.layer===d.layer)&&!m.layers.some(a=>a.layer===d.layer)); const an=CONS.analyse(r); const cur=r.currency||"USD"; const M=x=>cur+" "+Math.round(x||0).toLocaleString();
  el.innerHTML=`<div class="card"><h3>Stacked conservatism - where safe assumptions compound into an unexplained liability - ${esc(r.name)}</h3><p class="muted">Each layer records what the instrument requires, what was adopted, and the multiplier between them. Layers in the same chain multiply; the analyser separates the part the instruments require (Binding) from the discretionary stack and flags chains with three or more discretionary layers or a discretionary multiplier of 1.3 or more. Verbs follow the proposal: Binding → Keep; Interpreted and precedent → Validate; Inherited and layered → Simplify; Historical assumption → Reframe. Indicative savings are shown only where a cost driver is entered and remain hypotheses until the quantification gate passes.</p>
  <div class="kpis"><div class="kpi"><small>Chains · flagged</small><b>${an.summary.chains} · <span class="${an.summary.flagged?"bad":"ok"}">${an.summary.flagged}</span></b></div><div class="kpi"><small>Layers · binding · discretionary</small><b>${an.summary.layers} · ${an.summary.binding} · ${an.summary.discretionary}</b></div><div class="kpi"><small>Largest discretionary multiplier</small><b>x${an.summary.maxDisc.toFixed(2)}</b></div><div class="kpi"><small>Auto-detected candidates</small><b>${det.length}</b></div></div>
  <h4>Chains</h4><table><thead><tr><th>Chain</th><th>Layers</th><th>Total multiplier</th><th>Required (binding)</th><th>Discretionary stack</th><th>Stack index</th><th>Severity</th><th>Indicative saving (gated)</th><th>Verbs</th></tr></thead><tbody>${an.rows.map(c=>`<tr class="${c.flag?"keyrow":""}"><td><b>${esc(c.chain)}</b></td><td class="num">${c.layers.length}</td><td class="num">x${c.total.toFixed(2)}</td><td class="num">x${c.required.toFixed(2)}</td><td class="num"><b>x${c.disc.toFixed(2)}</b> (${c.nDisc} layer${c.nDisc===1?"":"s"})</td><td class="num">${c.stackIndex.toFixed(2)}</td><td class="${c.severity==="High"?"bad":c.severity==="Medium"?"amber":"ok"}">${c.severity}</td><td class="num">${c.indicativeSaving==null?"enter a cost driver":M(c.indicativeSaving)+" of "+M(c.driverCost)}</td><td><small>${c.verbs.map(v=>`${esc(v.verb)}: ${esc(v.layer.slice(0,50))}`).join("<br>")}</small></td></tr>`).join("")||'<tr><td colspan="9" class="muted">No layers yet - accept the auto-detected candidates or add from the library</td></tr>'}</tbody></table>
  <h4>Auto-detected candidates (from the record, the rule set and the ARO settings)</h4>${det.length?`<table><thead><tr><th>Chain</th><th>Layer</th><th>Category</th><th>Factor</th><th>Basis</th><th></th></tr></thead><tbody>${det.map((d,i)=>`<tr><td>${esc(d.chain)}</td><td>${esc(d.layer)}</td><td>${esc(d.category)}</td><td class="num">x${(+d.factor).toFixed(2)}</td><td><small>${esc(d.basis)}</small></td><td><button class="mini" data-acc="${i}">Accept</button></td></tr>`).join("")}</tbody></table>`:'<p class="muted">None outstanding.</p>'}
  <h4>Layers (edit the factor to what the record shows; set the category from the instrument, not from habit)</h4><div id="clg"></div>
  <h4>Library - typical layers to test <select id="clib">${CONS.LIB.map((l,i)=>`<option value="${i}">${esc(l[0])} - ${esc(l[1].slice(0,90))}</option>`).join("")}</select> <button id="cladd" class="mini">Add</button></h4>
  <p><button id="cpush">Push Validate / Simplify / Reframe layers to the requirements register and the opportunity register</button> <span id="cmsg" class="muted"></span></p>
  <p class="muted">Reading the result: a stack index of 1.0 means everything adopted is required; 1.5 means the site carries 50% more than the instruments demand across that chain. Three modest layers (1.15 x 1.2 x 1.3 = 1.79) are a common pattern - none looks unreasonable alone. Unstacking is a Tier 2 action with an approver and a reversal trigger, never a desktop edit.</p></div>`;
  const rr=()=>{ save(); rCons(r,el); };
  grid($("#clg"),m.layers.concat(m.accepted),[{k:"chain",label:"Chain",rows:1},{k:"layer",label:"Layer (what was adopted vs what is required)"},{k:"driver",label:"Cost driver / what it inflates",rows:1},{k:"driverCost",label:"Cost driver value (optional)",type:"num"},{k:"category",label:"Category (RvA)",type:"select",options:["Binding","Interpreted and precedent","Inherited and layered conservatism","Historical assumption","Unknown"]},{k:"factor",label:"Multiplier vs requirement",type:"num",step:0.01},{k:"basis",label:"Basis / clause",rows:1},{k:"verb",label:"Verb",type:"select",options:["Keep","Validate","Simplify","Reframe"]},{k:"reversible",label:"Reversible?",type:"select",options:["Yes","Partly","No"]},{k:"owner",label:"Owner",rows:1}],(del)=>{ m.layers=m.layers.concat(m.accepted); m.accepted=[]; rr(); },{newRow:()=>({chain:"Closure cost estimate",category:"Unknown",factor:1.0,verb:"Validate",reversible:"Yes"})});
  el.querySelectorAll('[data-acc]').forEach(b=>b.addEventListener('click',e=>{ const d=det[+e.target.dataset.acc]; m.accepted.push(Object.assign({verb:CONS.VERB[d.category]||"Validate",reversible:"Yes",owner:""},d)); log(r,"Conservatism layer accepted: "+d.layer.slice(0,80)); rr(); }));
  $("#cladd").addEventListener('click',()=>{ const l=CONS.LIB[+$("#clib").value]; m.layers.push({chain:l[0],layer:l[1],driver:l[2],category:l[3],factor:l[4],basis:l[5],verb:CONS.VERB[l[3]]||"Validate",reversible:"Yes",owner:""}); rr(); });
  $("#cpush").addEventListener('click',()=>{ let n=0; for(const l of m.layers.concat(m.accepted)){ const v=l.verb||CONS.VERB[l.category]; if(v==="Keep") continue; if(!r.rva.some(x=>x.statement===l.layer)){ r.rva.push({id:`RVA-${r.code}-${String(r.rva.length+1).padStart(2,"0")}`,statement:l.layer,feature:l.driver||"",category:l.category==="Historical assumption"?"Inherited and layered conservatism":l.category,instrument:"",clause:l.basis||"",verb:v,status:"Open"}); n++; } if(!r.opps.some(o=>o.text===`Unstack: ${l.layer}`)){ r.opps.push({id:`OPP-${r.code}-${String(r.opps.length+1).padStart(2,"0")}`,type:"Cost-to-risk",text:`Unstack: ${l.layer}`,change:v==="Simplify"?"reduce":"redesign",status:"Hypothesis",votes:{},source:`Stacked conservatism (${l.chain}, x${(+l.factor||1).toFixed(2)})`}); n++; } } log(r,`${n} conservatism items pushed to RvA and opportunities`); save(); $("#cmsg").textContent=`${n} item(s) pushed - approver and reversal trigger to be set on each.`; }); }

// ---------- Decision platform extensions: calibration & learning loop, portfolio investment optimiser, decision ledger & decision-ready package, portfolio command view
const GRADE_REF={E1:{n:2,mean:1.00,lo:1,hi:1},E2:{n:9,mean:0.67,lo:0,hi:1},E3:{n:8,mean:1.00,lo:0,hi:2},W:{n:7,mean:2.14,lo:2,hi:3}}; // published pilot calibration (desktop record -> site-confirmed, one site, Oct 2026) - reference only
function calib(){ if(!DB.calibration) DB.calibration={pairs:[],notes:""}; return DB.calibration; }
function harvestPairs(){ const out=[]; for(const r of Object.values(DB.records)){ const revs=(r.revisions||[]); if(!revs.length) continue; const base=revs[0]; const confirmed=(r.basis||"").toLowerCase().includes("site-confirmed")||(r.workshop&&r.workshop.date)||r.criteria.every(c=>c.accepted); if(!confirmed) continue; base.criteria.forEach((c,i)=>{ const now=r.criteria[i]; if(!now) return; if(c.rating!==now.rating||c.grade!==now.grade) out.push({site:r.code,criterion:c.id,grade:c.grade,desktop:c.rating,confirmed:now.rating,when:now.accepted?(r.workshop.date||""):"",source:`revision ${base.rev} -> current`}); else out.push({site:r.code,criterion:c.id,grade:c.grade,desktop:c.rating,confirmed:now.rating,when:r.workshop.date||"",source:`revision ${base.rev} -> current`}); }); } return out; }
function calibStats(pairs){ const by={}; for(const p of pairs){ const g=p.grade||"?"; (by[g]=by[g]||[]).push((+p.confirmed||0)-(+p.desktop||0)); } const q=(a,f)=>{ const s=a.slice().sort((x,y)=>x-y); return s[Math.min(s.length-1,Math.floor(f*s.length))]; }; return Object.fromEntries(Object.entries(by).map(([g,a])=>[g,{n:a.length,mean:a.reduce((x,y)=>x+y,0)/a.length,p10:q(a,0.1),p90:q(a,0.9),up:a.filter(x=>x>0).length,down:a.filter(x=>x<0).length,same:a.filter(x=>x===0).length,proposedLo:Math.max(0,-Math.min(0,q(a,0.1))),proposedHi:Math.max(0,q(a,0.9))}])); }
function rCalib(r,el){ const c=calib(); const harvested=harvestPairs(); const all=c.pairs.concat(harvested); const st=calibStats(all);
  el.innerHTML=`<div class="card"><h3>Calibration and learning loop - desktop ratings vs site-confirmed ratings</h3><p class="muted">Every workshop produces pairs (what the desktop said, what the site confirmed). The loop turns them into evidence-grade bound widths: the proposed lower bound is the 10th percentile of the shift, the upper bound the 90th. Pairs are harvested automatically from records that have a frozen revision and a site-confirmed state; you can also paste pairs (site, criterion, grade, desktop, confirmed). A proposed table becomes a calibration case for the framework steward - it never changes the production rule set directly.</p>
  <div class="kpis"><div class="kpi"><small>Pairs (pasted + harvested)</small><b>${c.pairs.length} + ${harvested.length}</b></div><div class="kpi"><small>Grades covered</small><b>${Object.keys(st).join(", ")||"-"}</b></div><div class="kpi"><small>Reference (published pilot, one site)</small><b>E2 +0.67 · E3 +1.00 · W +2.14</b></div></div>
  <h4>Shift statistics by evidence grade at the time of the desktop rating</h4><table><thead><tr><th>Grade</th><th>n</th><th>Mean shift</th><th>p10</th><th>p90</th><th>Up / same / down</th><th>Proposed bounds (−lo / +hi)</th><th>Current v3.4c</th><th>Reference pilot</th></tr></thead><tbody>${["E1","E2","E3","E4","W"].map(g=>{ const s=st[g]; const cur={E1:"0/0",E2:"0/0",E3:"-1/+1",E4:"-1/+2",W:"-1/+0"}[g]; const ref=GRADE_REF[g]; return `<tr><td><b>${g}</b></td><td class="num">${s?s.n:0}</td><td class="num">${s?s.mean.toFixed(2):"-"}</td><td class="num">${s?s.p10:"-"}</td><td class="num">${s?s.p90:"-"}</td><td>${s?`${s.up} / ${s.same} / ${s.down}`:"-"}</td><td class="num"><b>${s?`-${s.proposedLo} / +${s.proposedHi}`:"-"}</b></td><td class="num">${cur}</td><td class="num">${ref?`n ${ref.n}, mean +${ref.mean.toFixed(2)} (${ref.lo}..${ref.hi})`:"-"}</td></tr>`; }).join("")}</tbody></table>
  <h4>Paste pairs (CSV: site, criterion, grade, desktop, confirmed, date)</h4><textarea id="cpairs" rows="3" placeholder="HVW,T3,E3,2,3,2026-10-30"></textarea><p><button id="cpload">Add pairs</button> <button id="cpcase">Propose calibration case to the steward</button> <button id="cpexp" class="mini">Export pairs (CSV)</button> <span id="cpmsg" class="muted"></span></p>
  <div class="scroll" style="max-height:260px"><table><thead><tr><th>Site</th><th>Criterion</th><th>Grade</th><th>Desktop</th><th>Confirmed</th><th>Shift</th><th>When</th><th>Source</th></tr></thead><tbody>${all.map(p=>`<tr><td>${esc(p.site)}</td><td>${esc(p.criterion)}</td><td>${esc(p.grade)}</td><td class="num">${p.desktop}</td><td class="num">${p.confirmed}</td><td class="num">${(+p.confirmed-+p.desktop)>0?"+":""}${+p.confirmed-+p.desktop}</td><td>${esc(p.when||"")}</td><td><small>${esc(p.source||"pasted")}</small></td></tr>`).join("")||'<tr><td colspan="8" class="muted">No pairs yet - freeze the desktop revision before the workshop, confirm in the workshop, and the pairs harvest themselves</td></tr>'}</tbody></table></div>
  <p class="muted">Rule of thumb from the pilot: ratings that rested on a site statement moved +2 when the document arrived; consultant documents not independently reviewed moved +1; even regulator-grade evidence moved +0.67 when the desktop rater had defaulted undocumented items to 2. Thirty or more pairs per grade before the steward changes a bound.</p></div>`;
  $("#cpload").addEventListener('click',()=>{ const lines=$("#cpairs").value.split(/\r?\n/).map(l=>l.trim()).filter(Boolean); let n=0; for(const l of lines){ const x=l.split(/,|\t|;/).map(s=>s.trim()); if(x.length<5) continue; c.pairs.push({site:x[0],criterion:x[1].toUpperCase(),grade:x[2].toUpperCase(),desktop:+x[3],confirmed:+x[4],when:x[5]||"",source:"pasted"}); n++; } save(); $("#cpmsg").textContent=`${n} pair(s) added.`; rCalib(r,el); });
  $("#cpcase").addEventListener('click',()=>{ if(!r){ alert("Open a site first."); return; } r.govRecords=r.govRecords||[]; const text=`Calibration case from ${all.length} pairs: `+Object.entries(st).map(([g,s])=>`${g} n${s.n} mean ${s.mean.toFixed(2)} proposed -${s.proposedLo}/+${s.proposedHi}`).join("; "); r.govRecords.push({id:`calibration_case-${r.code}-${String(r.govRecords.length+1).padStart(3,"0")}`,type:"calibration_case",classification:"other",text,citation:"Calibration tab export",site:r.code,jurisdiction:r.jurisdiction,agent:"STEWARD",correlationId:"manual",created:new Date().toISOString().slice(0,10),state:"Draft",authoritative:false,provenance:[{step:"created",by:"user",when:new Date().toISOString()}]}); log(r,"Calibration case proposed to the steward"); save(); $("#cpmsg").textContent="Calibration case recorded (Draft) on Agents & governance."; });
  $("#cpexp").addEventListener('click',()=>{ const csv=["site,criterion,grade,desktop,confirmed,when,source"].concat(all.map(p=>[p.site,p.criterion,p.grade,p.desktop,p.confirmed,p.when||"",p.source||""].join(","))).join("\n"); const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"})); a.download="calibration-pairs.csv"; a.click(); }); }
// ---------- Portfolio investment optimiser (information purchases + unstacking + pathway actions under a budget)
function investCandidates(){ const out=[]; for(const r of Object.values(DB.records)){ const o=engineOpts(r); const c=crits(r); const jci=jciLevel(r).jci; const oo=Object.assign({},o,{rho:0.6,jcaOptions:[LATAF.JCA[jci],1.0]});
    for(const g of r.gaps.filter(x=>x.critical&&(x.status||"Open")!=="Closed")){ const cost=+g.cost||null; let lev=g._lev; if(lev==null){ try{ lev=LATAF.leverage(c,oo,{criteria:g.criteria||[],release:0},600).leverage; }catch(e){ lev=0; } g._lev=lev; } out.push({kind:"Information",site:r.code,item:`${g.id}: ${g.topic}`,cost,benefitPP:lev,benefit$:null,owner:g.owner||""}); }
    const cm=(r.conservatism||{}); for(const l of (cm.layers||[]).concat(cm.accepted||[])){ if((l.verb||CONS.VERB[l.category])==="Keep") continue; const f=+l.factor||1; if(f<=1.001||!(+l.driverCost)) continue; out.push({kind:"Unstacking",site:r.code,item:`${l.chain}: ${l.layer.slice(0,70)}`,cost:+l.validationCost||50000,benefitPP:null,benefit$:(+l.driverCost)*(1-1/f)*0.5,owner:l.owner||"",note:"50% probability the validation succeeds (edit on the layer)"}); }
    try{ PATHWAYS.T2F[r.code]=r.t2f; if(!PATHWAYS.TAGS[r.code]) PATHWAYS.TAGS[r.code]=(r.profile["Site attribute tags (comma separated)"]||"").split(",").map(x=>x.trim()).filter(Boolean); const rows=PATHWAYS.optimise(r.code,{recurring:r.recurring,aro:r.aro,natureBenefit:(r.fincase||{}).natureBenefit||0},{horizon:+r.fincase.horizon||50,rate:+r.fincase.rate||0.05,jca:LATAF.JCA[jci],fitFloor:0.34}); for(const p of rows.slice(0,3)) if(p.oneOff>0&&p.riskAdjusted>0) out.push({kind:"Pathway action",site:r.code,item:p.option.name,cost:p.oneOff,benefitPP:null,benefit$:p.riskAdjusted,owner:""}); }catch(e){} }
  return out; }
function knapsack(items,budget,key){ const rows=items.filter(x=>x.cost&&x[key]).map(x=>Object.assign({ratio:x[key]/x.cost},x)).sort((a,b)=>b.ratio-a.ratio); let spent=0, chosen=[]; for(const x of rows){ if(spent+x.cost<=budget){ chosen.push(x); spent+=x.cost; } } return {chosen,spent,rows}; }
function rInvest(r,el){ state.invInfo=state.invInfo??500000; state.invAct=state.invAct??2000000; const cands=investCandidates(); const info=knapsack(cands.filter(x=>x.kind==="Information"),state.invInfo,"benefitPP"); const act=knapsack(cands.filter(x=>x.kind!=="Information"),state.invAct,"benefit$"); const cur="USD"; const M=x=>cur+" "+Math.round(x||0).toLocaleString(); const unpriced=cands.filter(x=>!x.cost).length;
  el.innerHTML=`<div class="card"><h3>Portfolio investment optimiser - for a given budget, which information purchases and actions buy the most</h3><p class="muted">Two budgets, two currencies of benefit. Information: expected gain in P(achievable or better), in percentage points, per decision-critical gap (leverage from the engine, 600 draws). Actions: expected money - unstacking layers (indicative saving x 50% validation probability) and the top pathway options (risk-adjusted expected value). Greedy by benefit per cost; everything stays a hypothesis until the quantification gate passes. ${unpriced?`<b class="amber">${unpriced} candidate(s) have no cost - price them on their tabs to make them eligible.</b>`:""}</p>
  <div class="kpis"><div class="kpi"><small>Information budget</small><input type="number" id="ibud" value="${state.invInfo}" style="width:130px"></div><div class="kpi"><small>Action budget</small><input type="number" id="abud" value="${state.invAct}" style="width:130px"></div><div class="kpi"><small>Information selected</small><b>${info.chosen.length} items · ${M(info.spent)} · +${info.chosen.reduce((s,x)=>s+x.benefitPP,0).toFixed(1)} pp</b></div><div class="kpi"><small>Actions selected</small><b>${act.chosen.length} items · ${M(act.spent)} · ${M(act.chosen.reduce((s,x)=>s+x.benefit$,0))} expected</b></div></div>
  <h4>Information purchases ranked by leverage per cost</h4><table><thead><tr><th>Site</th><th>Gap</th><th>Cost to close</th><th>Leverage (pp)</th><th>pp per 100k</th><th>Owner</th><th>Selected</th></tr></thead><tbody>${info.rows.map(x=>`<tr class="${info.chosen.includes(x)?"keyrow":""}"><td>${esc(x.site)}</td><td>${esc(x.item)}</td><td class="num">${M(x.cost)}</td><td class="num">${x.benefitPP.toFixed(1)}</td><td class="num">${(x.ratio*100000).toFixed(1)}</td><td>${esc(x.owner)}</td><td>${info.chosen.includes(x)?"✓":""}</td></tr>`).join("")||'<tr><td colspan="7" class="muted">No priced decision-critical gaps</td></tr>'}</tbody></table>
  <h4>Actions ranked by expected value per cost</h4><table><thead><tr><th>Site</th><th>Kind</th><th>Item</th><th>Cost</th><th>Expected benefit</th><th>Ratio</th><th>Selected</th></tr></thead><tbody>${act.rows.map(x=>`<tr class="${act.chosen.includes(x)?"keyrow":""}"><td>${esc(x.site)}</td><td>${esc(x.kind)}</td><td>${esc(x.item)}<br><small>${esc(x.note||"")}</small></td><td class="num">${M(x.cost)}</td><td class="num">${M(x.benefit$)}</td><td class="num">${x.ratio.toFixed(2)}</td><td>${act.chosen.includes(x)?"✓":""}</td></tr>`).join("")||'<tr><td colspan="7" class="muted">No priced actions (enter cost drivers on Stacked conservatism; pathway options need recurring cost and provision on the profile)</td></tr>'}</tbody></table>
  <p><button id="invpush">Record the selected set as a decision (ledger)</button> <span id="invmsg" class="muted"></span></p></div>`;
  $("#ibud").addEventListener('change',e=>{ state.invInfo=+e.target.value; rInvest(r,el); }); $("#abud").addEventListener('change',e=>{ state.invAct=+e.target.value; rInvest(r,el); });
  $("#invpush").addEventListener('click',()=>{ if(!r){ alert("Open a site to hold the decision record."); return; } r.decisions=r.decisions||[]; r.decisions.push({id:`DEC-${r.code}-${String(r.decisions.length+1).padStart(2,"0")}`,date:new Date().toISOString().slice(0,10),question:"Portfolio investment priorities for the period",options:`${cands.length} candidates (${cands.filter(x=>x.kind==="Information").length} information, ${cands.filter(x=>x.kind!=="Information").length} actions)`,chosen:info.chosen.map(x=>x.item).concat(act.chosen.map(x=>x.item)).join("; "),rationale:`Greedy by benefit per cost under budgets ${M(state.invInfo)} / ${M(state.invAct)}; expected +${info.chosen.reduce((s,x)=>s+x.benefitPP,0).toFixed(1)} pp and ${M(act.chosen.reduce((s,x)=>s+x.benefit$,0))}`,evidence:"Information plan leverage; stacked conservatism; pathway optimiser",confidence:{information:"",evidence:"",applicability:"",recommendation:"Medium"},dissent:"",approver:"",reversal:"Re-run when a gap closes or a budget changes",review:"",status:"Proposed"}); log(r,"Investment priorities recorded as a decision"); save(); $("#invmsg").textContent="Decision recorded on the ledger."; }); }
// ---------- Decision ledger and decision-ready package
const DEC_TEMPLATES=[["Headline category and next step","Which decision category does the record support, and what is the next step?"],["Transition pathway","Which pathway is preferred, under what conditions, and which are held open?"],["Unstacking a conservatism layer","Which layer is validated, simplified or reframed, by whom, with what reversal trigger?"],["Quantification","Which saving or liability change is adopted, and does the prerequisite gate pass?"],["Information purchase","Which gaps are closed first, at what cost, for what leverage?"],["Standards compliance position","Which requirements are met, partially met or not met, and what closes the gap?"],["Re-mining / re-use hypothesis","Is the facility worth a Class 4 study?"]];
function decisionPackage(r){ const res=LATAF.run(crits(r),engineOpts(r)); const ic=(typeof GOV!=="undefined")?GOV.informationConfidence(r):null; const an=(typeof CONS!=="undefined")?CONS.analyse(r):null; const bind=r.rva.filter(x=>x.category==="Binding"); const L=[`# Decision-ready package - ${r.name} (${r.code}) - ${new Date().toISOString().slice(0,10)}`,"",`## Position`,`${res.decision}: TRI ${fmt(res.TRI)} [${fmt(res.TRI_low)}-${fmt(res.TRI_high)}] under ${LATAF.RULES[state.version].label}; category ${res.band}; ${res.cls}. ${res.result}`,"",`## Evidence`,`${r.evidence.length} documents; grades ${JSON.stringify(Object.fromEntries(["E1","E2","E3","E4","W"].map(g=>[g,r.criteria.filter(c=>c.grade===g).length])))}; ${r.gaps.filter(g=>g.critical&&(g.status||"Open")!=="Closed").length} open decision-critical gaps.`,"",`## Confidence`,ic?`Information ${ic.level} (weakest sub-rating ${ic.weakest}; consequence ${ic.consequence}); decision outcomes available: ${ic.allowed.join(" / ")}${ic.mandatoryEscalation?" - escalation mandatory":""}.`:"-","",`## Constraints (binding requirements)`,...(bind.length?bind.map(x=>`- ${x.statement} (${x.instrument||""} ${x.clause||""})`):["- none registered"]),"",`## Opportunities`,...(r.opps.length?r.opps.map(o=>`- ${o.id} ${o.text} [${o.status||""}]`):["- none"]),"",`## Stacked conservatism`,an&&an.rows.length?an.rows.map(c=>`- ${c.chain}: total x${c.total.toFixed(2)}, required x${c.required.toFixed(2)}, discretionary x${c.disc.toFixed(2)} (${c.severity})`).join("\n"):"- not assessed","",`## Dependencies`,...((r.govDeps||[]).filter(d=>d.status!=="Closed").map(d=>`- ${d.domain}: ${d.question} (${d.status})`)),"",`## Risks`,...(r.risks.slice(0,8).map(k=>`- ${k.id} ${k.text} (${k.residual||""})`)),"",`## Next action`,`${nextAction(r)}`,"",`## Narrative`,narrative(r),"",`## Decisions taken`,...((r.decisions||[]).map(d=>`- ${d.id} ${d.date} ${d.question} -> ${d.chosen} [${d.status}; approver ${d.approver||"-"}; reversal: ${d.reversal||"-"}]`))]; return L.join("\n"); }
function rDecisions(r,el){ r.decisions=r.decisions||[]; el.innerHTML=`<div class="card"><h3>Decision ledger and decision-ready package - ${esc(r.name)}</h3><p class="muted">Every decision as a record: the question, the options considered, what was chosen and why, the evidence relied on, the four confidences, dissent, approver, reversal trigger and review date. The package assembles position, evidence, confidence, constraints, opportunities, dependencies, risks and next action from the record - the standard return structure of the governance architecture.</p>
  <p>New decision from a template: <select id="dtpl">${DEC_TEMPLATES.map((t,i)=>`<option value="${i}">${esc(t[0])}</option>`).join("")}</select> <button id="dadd" class="mini">Add</button> <button id="dpkg">Download the decision-ready package (Markdown)</button> <button id="dpkgj" class="mini">JSON</button></p><div id="dgrid"></div></div>`;
  grid($("#dgrid"),r.decisions,[{k:"id",label:"ID",rows:1},{k:"date",label:"Date",rows:1},{k:"question",label:"Question"},{k:"options",label:"Options considered"},{k:"chosen",label:"Chosen"},{k:"rationale",label:"Rationale (evidence ids)"},{k:"dissent",label:"Dissent / minority view"},{k:"approver",label:"Approver (name, role)",rows:1},{k:"reversal",label:"Reversal trigger"},{k:"review",label:"Review date",rows:1},{k:"status",label:"Status",type:"select",options:["Proposed","Approved","Superseded","Reversed"]}],()=>save(),{newRow:n=>({id:`DEC-${r.code}-${String(n+1).padStart(2,"0")}`,date:new Date().toISOString().slice(0,10),status:"Proposed"})});
  $("#dadd").addEventListener('click',()=>{ const t=DEC_TEMPLATES[+$("#dtpl").value]; r.decisions.push({id:`DEC-${r.code}-${String(r.decisions.length+1).padStart(2,"0")}`,date:new Date().toISOString().slice(0,10),question:t[1],options:"",chosen:"",rationale:"",dissent:"",approver:"",reversal:"",review:"",status:"Proposed"}); save(); rDecisions(r,el); });
  $("#dpkg").addEventListener('click',()=>{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([decisionPackage(r)],{type:"text/markdown"})); a.download=`${r.code}-decision-package.md`; a.click(); });
  $("#dpkgj").addEventListener('click',()=>{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([JSON.stringify({site:r.code,generated:new Date().toISOString(),engine:LATAF.run(crits(r),engineOpts(r)),confidence:(typeof GOV!=="undefined")?GOV.informationConfidence(r):null,conservatism:(typeof CONS!=="undefined")?CONS.analyse(r).rows:null,decisions:r.decisions,opportunities:r.opps,binding:r.rva.filter(x=>x.category==="Binding"),gaps:r.gaps,dependencies:r.govDeps||[]},null,1)],{type:"application/json"})); a.download=`${r.code}-decision-package.json`; a.click(); }); }
// ---------- Portfolio command view
function rCommand(r0,el){ const rows=Object.values(DB.records).map(r=>{ const res=LATAF.run(crits(r),engineOpts(r)); const ic=(typeof GOV!=="undefined")?GOV.informationConfidence(r):null; const an=(typeof CONS!=="undefined")?CONS.analyse(r):{rows:[],summary:{flagged:0,maxDisc:1}}; const disc=an.rows.reduce((s,c)=>s+(c.indicativeSaving||0),0); const gaps=r.gaps.filter(g=>g.critical&&(g.status||"Open")!=="Closed"); const deadline=r.profile["Hard statutory deadline (if any)"]||""; const urgency=(deadline&&!/none|n\/a|^-?$/i.test(deadline)?3:0)+(ic&&ic.mandatoryEscalation?3:0)+(an.summary.flagged?2:0)+(gaps.length?1:0)+(res.decision==="Escalate decision"?2:0); return {r,res,ic,an,disc,gaps,deadline,urgency,nature:(r.fincase||{}).natureBenefit||0}; }).sort((a,b)=>b.urgency-a.urgency);
  const M=x=>"USD "+Math.round(x||0).toLocaleString(); const maxL=Math.max(1,...rows.map(x=>+x.r.aro||0)); const bar=(v,cls)=>`<div class="bar" style="width:160px;display:inline-block;vertical-align:middle"><div class="fill ${cls}" style="width:${Math.min(100,100*v/maxL)}%"></div></div>`;
  el.innerHTML=`<div class="card"><h3>Portfolio command view - readiness, liability, what is discretionary, and where to act first</h3><p class="muted">One line per site under ${esc(LATAF.RULES[state.version].label)}. "Act first" orders sites by: a hard statutory deadline, mandatory escalation (low confidence x high consequence), a flagged conservatism stack, open decision-critical gaps and an Escalate headline. Liability bars are the recorded provision; the discretionary stack and nature value are gated hypotheses until validated.</p>
  <div class="kpis"><div class="kpi"><small>Sites</small><b>${rows.length}</b></div><div class="kpi"><small>Total recorded provision</small><b>${M(rows.reduce((s,x)=>s+(+x.r.aro||0),0))}</b></div><div class="kpi"><small>Total recurring cost / yr</small><b>${M(rows.reduce((s,x)=>s+(+x.r.recurring||0),0))}</b></div><div class="kpi"><small>Discretionary stack (indicative, gated)</small><b>${M(rows.reduce((s,x)=>s+x.disc,0))}</b></div><div class="kpi"><small>Nature asset value recorded</small><b>${M(rows.reduce((s,x)=>s+x.nature,0))}</b></div><div class="kpi"><small>Open decision-critical gaps</small><b>${rows.reduce((s,x)=>s+x.gaps.length,0)}</b></div></div>
  <table><thead><tr><th>Act first</th><th>Site</th><th>Headline</th><th>TRI [range]</th><th>Information confidence</th><th>Provision</th><th>Recurring / yr</th><th>Discretionary stack</th><th>Nature value</th><th>Open critical gaps</th><th>Deadline</th><th>State</th><th>Next action</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="${i===0?"keyrow":""}"><td class="num">${x.urgency}</td><td><b>${esc(x.r.name)}</b><br><small>${esc(x.r.pathway)}</small></td><td>${badge(x.res.decision)}</td><td class="num">${fmt(x.res.TRI)} <small>[${fmt(x.res.TRI_low)}-${fmt(x.res.TRI_high)}]</small></td><td class="${x.ic?(x.ic.level==="Low"?"bad":x.ic.level==="Medium"?"amber":"ok"):""}">${x.ic?x.ic.level+(x.ic.mandatoryEscalation?" - escalate":""):"-"}</td><td class="num">${bar(+x.r.aro||0,"amber")} ${M(x.r.aro)}</td><td class="num">${M(x.r.recurring)}</td><td class="num">${x.an.rows.length?`x${x.an.summary.maxDisc.toFixed(2)} · ${M(x.disc)}`:"-"}</td><td class="num">${x.nature?M(x.nature):"-"}</td><td class="num">${x.gaps.length}</td><td><small>${esc(x.deadline||"-")}</small></td><td>${esc(x.r.state)}</td><td><small>${esc(nextAction(x.r))}</small></td></tr>`).join("")}</tbody></table>
  <p class="muted">Reading it: a site can be low on readiness and still not first in the queue if nothing is binding its timing; a site with a modest TRI but a x2 discretionary stack is where money is found fastest; mandatory escalation is a governance event, not a rating.</p></div>`; }

// @include graph_ext.js

document.addEventListener('DOMContentLoaded',()=>{ load(); $("nav").innerHTML=TABS.map(([k,l])=>`<button data-tab="${k}" class="${k===state.tab?'on':''}">${l}</button>`).join(""); refreshSites();
  $("#site").addEventListener('change',e=>{DB.current=e.target.value; save(); renderTab();}); $("#version").addEventListener('change',e=>{state.version=e.target.value; renderTab();}); $("#th").addEventListener('change',e=>{state.th=e.target.value; renderTab();});
  $$('nav button').forEach(b=>b.addEventListener('click',e=>go(e.target.dataset.tab))); renderTab(); });
})();
